	["[on | off | add x y title | hidden | undo]  show or hide every EldoUI map pin, add a map note"] = "[on | off | add x y title | hidden | undo]  vis eller skjul alle EldoUI-kortnåle, tilføj en kortnote",
	["[on | off | toggle]  show every enabled unit frame with sample values to place and style them"] = "[on | off | toggle]  vis alle unitframes der er slået til, med eksempelværdier så du kan placere og tilpasse dem",
	["[on | off | toggle]  Streamer Mode: aliases in place of real names"] = "[on | off | toggle]  Streamertilstand: aliasser i stedet for rigtige navne",
	["[open | level | pin <id> [n] | unpin <id> | clear]  the Profession Planner"] = "[open | level | pin <id> [n] | unpin <id> | clear]  fagplanlæggeren",
	["[post]  open the ready check report, or post its summary to the group"] = "[post]  åbn klar-tjek-rapporten, eller del resuméet i gruppen",
	["[questID]  is a quest new in WoW: Forever? Without an ID: the quest window's quest"] = "[questID]  er questen ny i WoW: Forever? Uden ID: questen i questvinduet",
	["[seconds | cancel]  start or cancel the group pull countdown (leader or assist)"] = "[seconds | cancel]  start eller annuller gruppens pull-nedtælling (leder eller assistent)",
	["[spells | weapons | config | on | off]  the Training window: what your trainer can teach you"] = "[spells | weapons | config | on | off]  vinduet Træning: hvad din træner kan lære dig",
	["[test]  Rare Alerts: open its settings, or show a test card"] = "[test]  Rare-advarsler: åbn dens indstillinger, eller vis et testkort",
	["[zone] x y [title] | list | print | closest | reset [zone|all]  waypoints and the arrow (also /way)"] = "[zone] x y [title] | list | print | closest | reset [zone|all]  waypoints og pilen (også /way)",
	["A 28 px button without rune counts."] = "En knap på 28 px uden runetal.",
	["A 32 px button that fades until the mouse is on it."] = "En knap på 32 px der toner ud indtil musen er over den.",
	["A 36 px button with rune counts; the list closes after a cast."] = "En knap på 36 px med runetal; listen lukker efter et cast.",
	["A 3D portrait in its own box, a name bar with race and class, a thick health bar, and level and class badges. Pairs with the Boxed party frames."] = "Et 3D-portræt i sin egen boks, en navnebjælke med race og klasse, en tyk livsbjælke samt level- og klassemærker. Passer til Boxed-grupperammerne.",
	["A 46 px button with rune counts, easy to hit."] = "En knap på 46 px med runetal, let at ramme.",
	["A bar under the browse page: role needed, level fits, not full, friends or guild, a name filter and dismissed listings."] = "En bjælke under søgesiden: rolle der mangler, passende level, ikke fuld, venner eller guild, et navnefilter og afviste opslag.",
	["A bar with ready check, role check, pull countdown, world markers, target icons and group tools for leaders and assists."] = "En bjælke med klar-tjek, rolletjek, pull-nedtælling, verdensmarkører, målikoner og gruppeværktøjer til ledere og assistenter.",
	["A box above the friends list. Rows that don't match what you type fade out; nothing is filtered away. The social window keeps its own search bar."] = "Et felt over vennelisten. Rækker der ikke matcher det du skriver, tones ned; intet bliver filtreret væk. Det sociale vindue beholder sin egen søgelinje.",
	["A bright line at the end of the fill."] = "En lys streg for enden af fyldet.",
	["A button (and key) for the item of the super-tracked quest, or of the first tracked quest that has one. Move it with /eui move."] = "En knap (og tast) til genstanden fra den valgte quest eller fra den første sporede quest der har en. Flyt den med /eui move.",
	["A button at vendors that sell items on your list. It buys what's missing, after the confirm question."] = "En knap hos købmænd der sælger genstande på din liste. Den køber det der mangler, efter bekræftelsesspørgsmålet.",
	["A button that casts Feed Pet on the chosen food."] = "En knap der caster Feed Pet på den valgte mad.",
	["A button that puts the preview's weapons away or draws them."] = "En knap der stikker forhåndsvisningens våben i skeden eller trækker dem.",
	["A button that removes all world markers (and all target icons on the icon row)."] = "En knap der fjerner alle verdensmarkører (og alle målikoner på ikonrækken).",
	["A button that sends the summary line to party or raid chat when you click it."] = "En knap der sender resumélinjen til gruppe- eller raidchatten når du klikker på den.",
	["A button with your tracked quest's item. Bind a key to it to use the item with your key press. It changes only out of combat."] = "En knap med genstanden fra din sporede quest. Tildel den en tast for at bruge genstanden med et tastetryk. Den skifter kun uden for kamp.",
	["A card at each level-up: how long the level took and the difference to your reference."] = "Et kort ved hvert level-up: hvor lang tid levelet tog, og forskellen til din reference.",
	["A card left of the top center. Click it to target the rare; right-click or x closes it. In combat it waits until combat ends."] = "Et kort til venstre for midten øverst. Klik på det for at vælge raren som mål; højreklik eller x lukker det. I kamp venter det til kampen er slut.",
	["A card when the game marks a treasure or chest on the minimap. Click it to set a waypoint."] = "Et kort når spillet markerer en skat eller en kiste på minikortet. Klik på det for at sætte et waypoint.",
	["A card when the game marks an event on the minimap. Click it to set a waypoint."] = "Et kort når spillet markerer en begivenhed på minikortet. Klik på det for at sætte et waypoint.",
	["A carved statue stands on the outer side of each orb, left of health and right of power. Only skins that draw statues show them, such as Infernal Stone."] = "En udskåret statue står på den yderste side af hver kugle, til venstre for liv og til højre for ressource. Kun skins med statuer viser dem, fx Infernal Stone.",
	["A character"] = "En karakter",
	["A chat line when a guild member comes online or goes offline."] = "En chatlinje når et guildmedlem logger ind eller ud.",
	["A chat line when a profession reaches the top of its rank, such as First Aid at 75/75, naming the rank to train. Also a card in the EldoUI alert lane when that lane is on."] = "En chatlinje når et fag når toppen af sit trin, fx First Aid på 75/75, med det trin der skal trænes. Også et kort i EldoUI's advarselsbane når den bane er slået til.",
	["A chat line when a waypoint is added, removed or reached."] = "En chatlinje når et waypoint tilføjes, fjernes eller nås.",
	["A check box on every letter and a bar under the mailbox: open the checked letters, or return them to their senders (asks first)."] = "Et afkrydsningsfelt på hvert brev og en bjælke under postkassen: åbn de afkrydsede breve, eller send dem tilbage til afsenderne (spørger først).",
	["A check mark instead of the count once you have enough of a reagent."] = "Et flueben i stedet for antallet når du har nok af et reagens.",
	["A check mark on what is done; nothing is hidden."] = "Et flueben på det der er klaret; intet skjules.",
	["A class buff with less time left than this shows as running out (yellow)."] = "En klassebuff med mindre tid tilbage end dette vises som ved at løbe ud (gul).",
	["A class or role icon on the frame's edge. Round in the Blizzard and Classic skins, square in Modern (Layout and style > Appearance)."] = "Et klasse- eller rolleikon på rammens kant. Rundt i Blizzard- og Classic-skinnet, firkantet i Modern (Layout og stil > Udseende).",
	["A clear EldoUI prompt with who, where and a countdown. You still click Accept; nothing is accepted for you."] = "En tydelig EldoUI-forespørgsel med navn, sted og nedtælling. Du klikker stadig selv på Accepter. Intet accepteres for dig.",
	["A click puts it on %s."] = "Et klik lægger den på %s.",
	["A column of gear slots on the preview showing what it wears; click one to take just that piece off."] = "En kolonne med udstyrspladser på forhåndsvisningen der viser hvad den har på; klik på en for kun at tage den del af.",
	["A column with each member's answer to the ready check: ready, not ready or waiting."] = "En kolonne med hvert medlems svar på klar-tjekket: klar, ikke klar eller venter.",
	["A column with the class buffs a member is missing."] = "En kolonne med de klassebuffs et medlem mangler.",
	["A compact 7 x 2 block with the bags on top."] = "En kompakt blok på 7 x 2 med taskerne øverst.",
	["A consumable buff or weapon enchant with less time left than this shows (yellow)."] = "En forbrugsbuff eller våbenenchant med mindre tid tilbage end dette vises (gul).",
	["A copy of the active scale that you can rename and tune."] = "En kopi af den aktive skala som du kan omdøbe og justere.",
	["A countdown bar when the group finder says your dungeon is ready."] = "En nedtællingsbjælke når gruppesøgeren siger at dit dungeon er klar.",
	["A countdown on the ready check and battleground pop-up."] = "En nedtælling på klar-tjekket og pop op-vinduet for battlegrounds.",
	["A cutscene or movie you already watched (on any character) is skipped. /eui cutscenes forget plays them again. Off by default."] = "En cutscene eller film du allerede har set (på en af dine karakterer), springes over. /eui cutscenes forget afspiller dem igen. Slået fra som standard.",
	["A dark overlay over the bar that keeps the name readable."] = "En mørk overlejring over bjælken der holder navnet læsbart.",
	["A demon you did not allow is out"] = "En dæmon du ikke har tilladt, er fremme",
	["A different health bar texture."] = "En anden tekstur til livsbjælken.",
	["A dungeon or battleground invite brings the interface back at once, so you can answer it."] = "En invitation til et dungeon eller et battleground bringer brugerfladen tilbage med det samme, så du kan svare.",
	["A faint shadow around the panel so it lifts off bright zones."] = "En svag skygge om panelet, så det skiller sig ud fra lyse zoner.",
	["A faint tint on every other row of the sent log."] = "En svag farvetone på hver anden række i afsendelsesloggen.",
	["A faint tint on every other row."] = "En svag farvetone på hver anden række.",
	["A flat EldoUI box behind every alert; no glow and shine flash."] = "En flad EldoUI-boks bag hver advarsel; ingen glød og intet glimt.",
	["A flat Ignore tab next to Friends / Recent Allies (under the social window) that opens Blizzard's ignore list (also in the Contacts menu)."] = "En flad fane Ignorer ved siden af Friends / Recent Allies (under det sociale vindue) der åbner Blizzards ignoreringsliste (findes også i menuen Contacts).",
	["A full panel with the art style's frame line, bronze under WoW Forever."] = "Et fuldt panel med grafikstilens rammelinje, bronze under WoW Forever.",
	["A glow on the shield or an imbue while it is missing. The shield's glow shows out of combat only: the game hides your auras from addons in combat (the faded icon still shows)."] = "En glød på skjoldet eller en imbue mens den mangler. Skjoldets glød vises kun uden for kamp: spillet skjuler dine auraer for addons i kamp (det udtonede ikon vises stadig).",
	["A glow round this frame while its unit is your target (look: the Glows page, \"Unit frames: your target\")."] = "En glød rundt om rammen mens dens enhed er dit mål (udseende: siden Glød, \"Unitframes: dit mål\").",
	["A gold fill shows the XP waiting in finished quests you have not handed in yet."] = "En guldfarvet fyldning viser den XP der venter i færdige quests som du ikke har afleveret endnu.",
	["A green arrow with the gain in the tooltip's info area. Its visibility (Always / Shift ...) is set on the Tooltip page."] = "En grøn pil med gevinsten i tooltippens infoområde. Hvornår den vises (Altid / Shift ...), indstilles på siden Tooltip.",
	["A green arrow with the gain when an item beats what you wear, by your active scale."] = "En grøn pil med gevinsten når en genstand slår det du har på, efter din aktive skala.",
	["A grip in the bottom-right corner; the size is remembered."] = "Et greb i nederste højre hjørne; størrelsen huskes.",
	["A harmless pop-up to check the look and the position. It does nothing."] = "Et harmløst pop op-vindue til at tjekke udseende og placering. Det gør ingenting.",
	["A large icon when a class buff, gathering tracking or a chosen consumable is missing or running out."] = "Et stort ikon når en klassebuff, indsamlingssporing eller en valgt forbrugsvare mangler eller er ved at løbe ud.",
	["A leveling timer that races your own best: time on this level, the difference to your best character, a card at each level-up and a Splits tab in the Characters window."] = "Tidtagning til leveling hvor du kappes med din egen bedste tid: tid på dette level, forskellen til din bedste karakter, et kort ved hvert level-up og fanen Mellemtider i Karakterer-vinduet.",
	["A light sheen on your target's bar."] = "En let glans på dit måls bjælke.",
	["A lighter fill shows how far your rested bonus reaches."] = "En lysere fyldning viser hvor langt din udhvilede bonus rækker.",
	["A line in the quest window, the quest log and the dialog view that says where a quest sits in its chain, like Part 2 of 5 and the next step. On by default."] = "En linje i questvinduet, questloggen og dialogvisningen der viser hvor en quest ligger i sin kæde, fx Del 2 af 5 og det næste trin. Slået til som standard.",
	["A line in your chat each time the layer you are on changes."] = "En linje i chatten hver gang dit layer skifter.",
	["A line under the click-binding window: whether EldoUI shows these bindings on party and raid tooltips, with a button to its settings."] = "En linje under klikbindingsvinduet: om EldoUI viser disse bindinger i tooltips for gruppe og raid, med en knap til indstillingerne.",
	["A line with the place and a map link in your own chat frame. Nothing is sent to others. Off by default: the card and the sound already tell you."] = "En linje med stedet og et kortlink i dit eget chatvindue. Intet sendes til andre. Fra som standard: kortet og lyden fortæller dig det allerede.",
	["A list beside the trainer with everything it teaches, now and at later levels, with rank, level and cost. With Training on, class trainers show that window instead."] = "En liste ved siden af træneren med alt den lærer fra sig, nu og på senere levels, med rang, level og pris. Med Træning slået til viser klassetrænere det vindue i stedet.",
	["A loadout is a saved set of four totems. Right-click Drop All to switch, save, rename, share or delete. A switch waits for out of combat."] = "Et loadout er et gemt sæt af fire totems. Højreklik på Sæt alle for at skifte, gemme, omdøbe, dele eller slette. Et skift venter til du er uden for kamp.",
	["A lower spell rank: %s changes only the rank number."] = "En lavere evnerang: %s ændrer kun rangnummeret.",
	["A menu holds up to %d entries."] = "En menu kan rumme op til %d punkter.",
	["A message when your pet's happiness drops to content or unhappy."] = "En besked når dit pets tilfredshed falder til tilfreds eller utilfreds.",
	["A mono font with colors and line numbers, like a code editor."] = "En monospace-skrifttype med farver og linjenumre som en kodeeditor.",
	["A name for the rule list."] = "Et navn til regellisten.",
	["a name was expected"] = "forventede et navn",
	["A new route shows the time so far with \"learning\"; the next flight on it shows the full time. Times come from your flights only."] = "En ny rute viser tiden indtil videre med \"lærer\"; næste flyvning på ruten viser den fulde tid. Tiderne kommer kun fra dine egne flyvninger.",
	["A note when a weapon imbue is running out or gone: in the Combat Text notification lane in combat, an alert card out of combat."] = "En besked når en våben-imbue er ved at løbe ud eller er væk: i Kamptekst-notifikationsbanen i kamp, et advarselskort uden for kamp.",
	["A note when fewer than %d of the chosen food are left. It comes again after you restock."] = "En påmindelse når der er færre end %d af den valgte mad tilbage. Den kommer igen når du har fyldt op.",
	["A note while your pet is set to passive."] = "En besked mens dit pet står på passiv.",
	["A panel behind the buttons."] = "Et panel bag knapperne.",
	["A panel behind the timer; off shows the text alone."] = "Et panel bag tidtagningen. Slået fra vises kun teksten.",
	["A panel behind the tracker in the EldoUI art style. None keeps Blizzard's background (opacity from Edit Mode)."] = "Et panel bag trackeren i EldoUI-grafikstilen. Uden panel beholdes Blizzards baggrund (opacitet fra Edit Mode).",
	["A panel in the EldoUI art style. Off keeps Blizzard's border."] = "Et panel i EldoUI's grafikstil. Når den er slået fra, beholdes Blizzards kant.",
	["A Pin button in the Loot Guide's Crafting details, and Alt-click on a recipe in the Alts window's Professions tab."] = "En Fastgør-knap i detaljerne på Loot Guides Crafting-side og Alt-klik på en opskrift under fanen Fag i Alts-vinduet.",
	["A Pin button on the game's profession window, next to the selected recipe."] = "En Fastgør-knap på spillets fagvindue ved siden af den valgte opskrift.",
	["A plan that starts with the talents you have now."] = "En plan der starter med de talenter du har nu.",
	["A plate near the middle of the screen that follows your settings as you change them."] = "En nameplate nær midten af skærmen der følger dine indstillinger mens du ændrer dem.",
	["A plate of the test plate's type, in its size, text size and cast bar."] = "En nameplate af testnameplatens type, med dens størrelse, tekststørrelse og castbar.",
	["A player on another layer invites you; you accept in the game's popup and leave the group once your layer changes. Each step is a click."] = "En spiller på et andet layer inviterer dig; du accepterer i spillets pop op-vindue og forlader gruppen når dit layer skifter. Hvert trin er et klik.",
	["A player..."] = "En spiller...",
	["A pulsing note above the reminders during a ready check when your own mana is low. Out of combat only."] = "En pulserende besked over påmindelserne under et klar-tjek når din egen mana er lav. Kun uden for kamp.",
	["A quest icon on mobs the game marks for one of your active quests."] = "Et questikon på mobs som spillet markerer til en af dine aktive quests.",
	["A quiet sighting shows"] = "En stille opdagelse viser",
	["A rare you know of yells or emotes nearby."] = "En rare du kender, råber eller laver en emote i nærheden.",
	["A rare's nameplate appears. Enemy nameplates must be on."] = "En rares nameplate dukker op. Fjendtlige nameplates skal være slået til.",
	["A ready icon for this spell, once you know it."] = "Et klar-ikon for denne evne når du kender den.",
	["A reagent you can craft (a bar, a leather, a thread) shows its own reagents under it, two steps deep."] = "Et reagens du selv kan lave (en barre, et læder, en tråd), viser sine egne reagenser under sig, to trin ned.",
	["A red zone at the end of your casts, as long as your current latency."] = "En rød zone for enden af dine casts, lige så lang som din nuværende latens.",
	["A restore adds what is missing but never empties a slot."] = "En gendannelse tilføjer det der mangler, men tømmer aldrig en plads.",
	["A restore starts with only the action bars checked."] = "Ved en gendannelse har kun handlingslinjerne flueben fra start.",
	["A restore starts with only the Edit Mode layout checked."] = "Ved en gendannelse har kun Edit Mode-layoutet flueben fra start.",
	["A restore starts with only the key bindings checked."] = "Ved en gendannelse har kun genvejstasterne flueben fra start.",
	["A riding trainer teaches it, next to the mount vendor of each race. The cost is the one a trainer asked, once you have opened one."] = "En ridetræner lærer dig det, ved siden af hver races mount-forhandler. Prisen er den en træner har bedt om når du har åbnet en.",
	["A row (left to right) or a column (top to bottom)."] = "En række (fra venstre mod højre) eller en kolonne (oppefra og ned).",
	["A row across or a column down."] = "En vandret række eller en lodret kolonne.",
	["A sample card of the EldoUI alert lane in its width and icon size."] = "Et eksempelkort fra EldoUI's advarselsbane i dens bredde og ikonstørrelse.",
	["A sample map in its shape, with the zone name and clock as set on the Text tab."] = "Et eksempelkort i den valgte form med zonenavn og ur som indstillet på fanen Tekst.",
	["A sample tooltip of your character in your text sizes, opacity and colors."] = "En eksempeltooltip for din karakter med dine tekststørrelser, din opacitet og dine farver.",
	["A scale gives each stat a value; an item's score is the sum. Starter scales are rough; tune one for your spec or paste a friend's."] = "En skala giver hver stat en værdi; en genstands score er summen. Startskalaerne er grove; juster en til din spec, eller indsæt en vens.",
	["A second bar with your shield, weapon imbues and shaman cooldowns. Click an icon to cast it."] = "En ekstra linje med dit skjold, dine våben-imbues og Shaman-cooldowns. Klik på et ikon for at caste det.",
	["A second row that puts skull, cross and the other icons on your target."] = "En ekstra række der sætter kranie, kryds og de andre ikoner på dit mål.",
	["A see-through background in your art style behind the line under each roll."] = "En gennemsigtig baggrund i din grafikstil bag linjen under hvert lootrul.",
	["A see-through compact list with buffs and the ready answer only."] = "En gennemsigtig, kompakt liste med kun buffs og klar-svaret.",
	["A see-through EldoUI panel behind the tracker."] = "Et gennemsigtigt EldoUI-panel bag trackeren.",
	["A see-through panel behind the rows."] = "Et gennemsigtigt panel bag rækkerne.",
	["A see-through panel behind the top-center widgets while any show."] = "Et gennemsigtigt panel bag widgets øverst i midten mens nogen af dem vises.",
	["A see-through window over the game."] = "Et gennemsigtigt vindue over spillet.",
	["A short flash over the bar when a cast ends (needs animations on, General)."] = "Et kort blink over bjælken når et cast slutter (kræver at animationer er slået til, Generelt).",
	["A short message when you enter and leave combat."] = "En kort besked når du går i kamp og ud af kamp.",
	["A short note when someone you marked Avoid joins your group."] = "En kort besked når en du har markeret som Undgå, kommer i din gruppe.",
	["A short popup when a member finishes an objective or the whole of a quest you share."] = "En kort pop op-besked når et medlem klarer et mål eller hele en quest som I deler.",
	["A short pulse on your gamepad for each alert, a longer one for a rare with a mount, pet, toy or set piece you don't own. Only while you play with a gamepad; quiet sightings don't pulse."] = "Et kort pulsslag på din gamepad for hver advarsel, et længere for en rare med en mount, et pet, et toy eller en setdel du ikke ejer. Kun mens du spiller med gamepad; stille opdagelser giver ingen puls.",
	["A short sound with each toast."] = "En kort lyd med hver pop op-besked.",
	["A short strip when a cast is interrupted."] = "En kort stribe når et cast bliver afbrudt.",
	["A slider under the trees that shows your plan as it stands at any level."] = "En skyder under træerne der viser din plan som den ser ud på et vilkårligt level.",
	["A slow glow. Its look is on the Glows page (Nameplates: target)."] = "En langsom glød. Dens udseende findes på siden Glød (Nameplates: mål).",
	["A small +/- button on the quest tracker's top row to fold it away; /eui tracker does the same. Remembered per character."] = "En lille knap (+/-) i questtrackerens øverste række til at folde den sammen; /eui tracker gør det samme. Huskes pr. karakter.",
	["A small box on the edge of an item tooltip with the Danish word for what the item is, such as Le on a scythe. The English name stays. Names never get a box."] = "En lille boks på kanten af en genstands tooltip med det danske ord for hvad genstanden er, fx Le på en Scythe. Det engelske navn bliver stående. Navne får aldrig en boks.",
	["A small box with your map coordinates. Click it to type coordinates and add a waypoint; right-click for more. Move it in move mode (Waypoint Coordinates)."] = "En lille boks med dine kortkoordinater. Klik på den for at skrive koordinater og tilføje et waypoint; højreklik for mere. Flyt den i flyttetilstand (Waypointkoordinater).",
	["A small button at the top right of the world map: click for the groups, Shift-click to show or hide everything."] = "En lille knap øverst til højre på verdenskortet: klik for grupperne, Shift-klik for at vise eller skjule alt.",
	["A small icon before each reagent."] = "Et lille ikon foran hvert reagens.",
	["A small label: minimap, nameplate, target, group or yell."] = "En lille etiket: minikort, nameplate, mål, gruppe eller råb.",
	["A small list beside the rare cards with this session's sightings. Click a line to set a waypoint, Shift-click to share it, right-click to remove it."] = "En lille liste ved siden af rare-kortene med denne sessions opdagelser. Klik på en linje for at sætte et waypoint, Shift-klik for at dele den, højreklik for at fjerne den.",
	["A small list of the pings you receive: time, sender and what they pinged. Place it with the \"Ping Feed\" mover (/eui move)."] = "En lille liste over de pings du modtager: tid, afsender og hvad der blev pinget. Placer den med flyttefeltet \"Ping Feed\" (/eui move).",
	["A small number on each talent of your plan: which of the plan's points takes it first. The talent's tooltip lists every point. Also shown on Blizzard's talent window while Show my plan is on."] = "Et lille tal på hvert talent i din plan: hvilket af planens point der tager det først. Talentets tooltip viser alle point. Vises også i Blizzards talentvindue mens Vis min plan er slået til.",
	["A small one-line panel toast and a short tooltip without dungeons."] = "En lille pop op-besked i et panel på én linje og en kort tooltip uden dungeons.",
	["A small panel with a master volume slider (mouse wheel works too). /eui volume shows or hides it; move it with /eui move."] = "Et lille panel med en skyder til hovedlydstyrken (musehjulet virker også). /eui volume viser eller skjuler det; flyt det med /eui move.",
	["A small panel with only the counts: who misses what, without member rows."] = "Et lille panel med kun tallene: hvem der mangler hvad, uden medlemsrækker.",
	["A small paw by pets and guardians."] = "En lille pote ved pets og guardians.",
	["A small spell icon before each ability."] = "Et lille evneikon foran hver evne.",
	["A small square on party frames per running buff totem: filled when the member has it, hollow when not, ? in combat (the game hides it then)."] = "En lille firkant på grupperammer pr. aktiv totembuff: udfyldt når medlemmet har den, ellers tom, ? i kamp (spillet skjuler det da).",
	["A small window with the numbers behind each bar: level or standing, progress, remaining, rested XP and finished quests, in foldable sections. Shift-click a bar opens it too."] = "Et lille vindue med tallene bag hver bjælke: level eller omdømmetrin, fremskridt, resterende, udhvilet XP og færdige quests i afsnit der kan foldes sammen. Shift-klik på en bjælke åbner det også.",
	["A snapshot holds your action slots, macros, key bindings and Edit Mode layout. Restore shows each change first and can be undone."] = "Et øjebliksbillede indeholder dine handlingspladser, makroer, genvejstaster og dit Edit Mode-layout. Gendan viser hver ændring først og kan fortrydes.",
	["A soft blue tint everywhere and no tag in the quest window."] = "En blød blå farvetone overalt og intet mærke i questvinduet.",
	["A sound for ready checks, role polls and battleground or dungeon ready, once per pop-up. It plays on the Master channel, so you hear it with game sound effects off."] = "En lyd ved klar-tjek, rolleafstemning, og når et battleground eller dungeon er klar, én gang pr. pop op-vindue. Den spiller på hovedkanalen, så du hører den, selv med spillets lydeffekter slået fra.",
	["A sound when a new reminder appears (at most every 3 seconds)."] = "En lyd når en ny påmindelse dukker op (højst hvert 3. sekund).",
	["A sound when you arrive. None for silence."] = "En lyd når du ankommer. Vælg Ingen for at slå lyden fra.",
	["A spell name or spell ID, or item: and an item ID (item:6948). Empty: the key does nothing."] = "Et evnenavn eller evne-ID, eller item: og et genstands-ID (item:6948). Tom: tasten gør intet.",
	["a spell, item, macro, mount or equipment set"] = "en evne, genstand, makro, mount eller et udstyrssæt",
	["A status mark after the name in place of Blizzard's icon: green online, yellow away, red busy, gray offline. With shape marks on, it also has a shape."] = "Et statusmærke efter navnet i stedet for Blizzards ikon: grøn online, gul væk, rød optaget, grå offline. Med formmærker slået til har det også en form.",
	["A strip under the bars or a name bar over them, for extra texts (Texts tab: attach a text to the info panel)."] = "En strimmel under bjælkerne eller en navnebjælke over dem, til ekstra tekster (fanen Tekster: knyt en tekst til infopanelet).",
	["A tab next to the friends tabs with the last 50 players you grouped with, your Player Notes mark and note on each, and an Add friend button. Needs the Player Notes module. On by default."] = "En fane ved siden af vennefanerne med de seneste 50 spillere du har været i gruppe med, dit mærke og din note fra Spillernoter på hver, og en knap Tilføj ven. Kræver modulet Spillernoter. Slået til som standard.",
	["A talent loadout keeps only the final ranks: the plan takes lower rows first. Reorder it in the planner."] = "En talentloadout indeholder kun hvert talents endelige rang: planen tager de lavere rækker først. Ændr rækkefølgen i planlæggeren.",
	["A talent path EldoUI suggests for your class."] = "En talentsti som EldoUI foreslår til din klasse.",
	["A test quest"] = "En testquest",
	["A text string of the plan to copy and share (!EUT1!)."] = "En tekststreng af planen som du kan kopiere og dele (!EUT1!).",
	["A text string with every rule, to share or keep."] = "En tekststreng med alle regler, til at dele eller gemme.",
	["A thin bar across the bottom edge of the screen that frames the interface."] = "En tynd bjælke langs skærmens nederste kant der indrammer brugerfladen.",
	["A thin bar across the top edge of the screen that frames the interface."] = "En tynd bjælke langs skærmens øverste kant der indrammer brugerfladen.",
	["A thin bar under each button that empties as its totem runs out."] = "En tynd bjælke under hver knap der tømmes efterhånden som totemmen udløber.",
	["A thin bar under each card with your own progress on the quest."] = "En tynd bjælke under hvert kort med dit eget fremskridt på questen.",
	["A thin bar with the unit's mana, rage or energy under the health bar."] = "En tynd bjælke under livsbjælken med enhedens mana, rage eller energy.",
	["A thin edge in the element's color under each button: green earth, orange fire, blue water, light blue air."] = "En tynd kant i elementets farve under hver knap: grøn jord, orange ild, blå vand, lyseblå luft.",
	["A thin line along the XP bar while an XP bonus runs, such as XP food or an event. The tooltip names each bonus and its time left either way."] = "En tynd linje langs XP-bjælken mens en XP-bonus kører, fx fra XP-mad eller et event. Tooltippen nævner hver bonus og dens resterende tid uanset hvad.",
	["A thin line between the game's text and the info area."] = "En tynd linje mellem spillets tekst og infoområdet.",
	["A thin line in your accent color on the inner edge of each panel."] = "En tynd linje i din accentfarve langs inderkanten af hvert panel.",
	["A thin timer bar under each button instead of countdown numbers."] = "En tynd tidsbjælke under hver knap i stedet for nedtællingstal.",
	["A third row for running the group. Each button is one click; nothing happens on its own."] = "En tredje række til at styre gruppen. Hver knap er ét klik; intet sker af sig selv.",
	["A tick on each zone header tracks or untracks every quest in that zone."] = "Et flueben ved hver zoneoverskrift slår sporing til eller fra for alle quests i zonen.",
	["A totem bar for shamans: one button per element drops your pick, pointing at it lists its totems, and Drop All drops the whole set."] = "En totemlinje til Shamans: én knap pr. element sætter dit valg (peg på den for at se dens totems), og Sæt alle sætter hele sættet.",
	["A totem bar with a picker per element, Drop All and timers, a cooldown bar for shields, imbues and shaman cooldowns, totem loadouts and totem buff squares on group frames. Shamans only."] = "En totemlinje med en vælger pr. element, Sæt alle og nedtællinger, en cooldownlinje til skjolde, imbues og Shaman-cooldowns, totem-loadouts og firkanter for totembuffs på grupperammer. Kun for Shamans.",
	["A Training tab under Blizzard's spellbook that lays this list over the spellbook pages."] = "En fane Træning under Blizzards evnebog som lægger denne liste over evnebogens sider.",
	["a value was expected"] = "forventede en værdi",
	["a waypoint"] = "et waypoint",
	["A whisper you send from the main chat opens that conversation's window."] = "En hvisken du sender fra hovedchatten, åbner vinduet til den samtale.",
	["A wide see-through banner with a large zone name and an accent line."] = "Et bredt, gennemsigtigt banner med et stort zonenavn og en accentlinje.",
	["A wide sent log for long subjects and many items."] = "En bred afsendelseslog til lange emner og mange genstande.",
	["A wider macro editor next to Blizzard's macro window: a syntax check with hints, a condition builder and an icon search by spell or item name. Saving happens out of combat."] = "En bredere makroeditor ved Blizzards makrovindue: syntakstjek med tips, betingelsesbygger og ikonsøgning efter evne eller genstand. Gemmer uden for kamp.",
	["A yellow note when a priest, mage, druid or paladin is in your group and you lack their buff. Information only. Off by default."] = "En gul besked når en Priest, Mage, Druid eller Paladin er i din gruppe og du mangler deres buff. Kun til information. Slået fra som standard.",
	["A zone to travel to or from: below are its transport stops with where each goes, and the boats, zeppelins, tram and portals that arrive there."] = "En zone at rejse til eller fra: nedenfor ses dens transportstop, og hvor hvert stop går hen, samt de både, zeppelinere, tog og portaler der ankommer dertil.",
	["Abilities before \"more\""] = "Evner før \"flere\"",
	["Abilities seen"] = "Evner set",
	["Ability log"] = "Evnelog",
	["Ability marks"] = "Evnemærker",
	["Ability, spell and item cooldown messages."] = "Beskeder om cooldowns på evner og genstande.",
	["Above the cast bar"] = "Over castbaren",
	["Above the Cooldown Manager"] = "Over Cooldown Manager",
	["Above the frame"] = "Over rammen",
	["Above the map"] = "Over kortet",
	["Above the window"] = "Over vinduet",
	["Absorb shields"] = "Absorberingsskjolde",
	["Accent border"] = "Accentkant",
	["Accent border: on."] = "Accentkant: til.",
	["Accent line"] = "Accentlinje",
	["Accent senders, 24 px toolbar, roomy log."] = "Afsendere i accentfarve, værktøjslinje på 24 px, rummelig log.",
	["Accent-colored headers"] = "Overskrifter i accentfarve",
	["Accept"] = "Accepter",
	["Accept quests automatically"] = "Accepter quests automatisk",
	["Accepts quests from NPCs when their window opens. Quests shared by other players are never accepted. Off by default."] = "Accepterer quests fra NPC'er når deres vindue åbner. Quests delt af andre spillere accepteres aldrig. Slået fra som standard.",
	["Achievement"] = "Achievement",
	["Achievement name, points and icon. Click opens it in the achievement window."] = "Achievementets navn, point og ikon. Et klik åbner det i achievementvinduet.",
	["Achievements and challenges"] = "Achievements og udfordringer",
	["Achievements, criteria and Legacy challenge alerts."] = "Advarsler om achievements, kriterier og Legacy-udfordringer.",
	["Across"] = "Vandret",
	["Across the whole screen width with numbers always shown, like the old Blizzard bar."] = "Over hele skærmens bredde med tal der altid vises, ligesom den gamle Blizzard-bjælke.",
	["Acting for you"] = "Handler på dine vegne",
	["Acting for you (off by default)"] = "Handler på dine vegne (fra som standard)",
	["Action slots that change (%d)"] = "Handlingspladser der ændres (%d)",
	["ActionCam"] = "ActionCam",
	["ActionCam is off: the game's camera settings were put back."] = "ActionCam er slået fra: spillets kameraindstillinger er sat tilbage.",
	["Active scale (this class)"] = "Aktiv skala (denne klasse)",
	["Acts for you when turned on: repairs all gear when you open a vendor who can repair, guild bank first if you choose it, then your own gold. Off until you pick it here or in the setup."] = "Handler på dine vegne når den er slået til: reparerer alt udstyr når du åbner en købmand der kan reparere, først med guildbanken hvis du vælger det, derefter med dit eget guld. Fra indtil du vælger den her eller i opsætningen.",
	["Acts for you when turned on: sells gray items and items on your Always sell list in batches of 12 at vendors. Retries refused sales if the sale limit is off. Off by default."] = "Handler på dine vegne når den er slået til. Sælger grå genstande og genstande på listen Sælg altid i hold på 12 hos købmænd. Prøver afviste salg igen hvis salgsgrænsen er slået fra. Fra som standard.",
	["Acts for you. Accept and turn in quests (never picks a reward) and skip plain vendor chat. Hold Shift to pause."] = "Handler på dine vegne. Accepterer og afleverer quests (vælger aldrig en belønning) og springer almindelig snak hos købmænd over. Hold Shift nede for at holde pause.",
	["Acts for you. Strangers' duels, invites, join requests and shared quests declined; duel and drunk spam hidden."] = "Handler på dine vegne. Dueller, invitationer, anmodninger om at blive med og delte quests fra fremmede afvises; spam om dueller og fuldskab skjules.",
	["Acts for you: a click on a reminder casts the missing buff or uses the consumable, one cast per click and never by itself."] = "Handler på dine vegne: et klik på en påmindelse caster den manglende buff eller bruger forbrugsvaren, én handling pr. klik og aldrig af sig selv.",
	["Acts for you: accepts quests from NPCs when their window opens, never quests other players share."] = "Handler på dine vegne: accepterer quests fra NPC'er når deres vindue åbner, aldrig quests som andre spillere deler.",
	["Acts for you: asks to buy what your restock list is missing when you open a vendor who sells it, and buys only after you say yes."] = "Handler på dine vegne: når du åbner en købmand der sælger det din genopfyldningsliste mangler, spørger den om du vil købe det, og den køber først når du siger ja.",
	["Acts for you: asks to fill your quiver or ammo pouch when you open a vendor who sells your ammo, and buys only after you say yes."] = "Handler på dine vegne: når du åbner en købmand der sælger din ammunition, spørger den om du vil fylde dit kogger eller din ammunitionspung, og den køber først når du siger ja.",
	["Acts for you: confirms Bind on Pickup items when you loot alone. Group loot and other confirmations still ask. Change this in Loot settings."] = "Handler på dine vegne: bekræfter Bind on Pickup-genstande når du looter alene. Gruppeloot og andre bekræftelser spørger stadig. Ændres under Loot-indstillinger.",
	["Acts for you: declines duel requests from people who aren't your friends, out of combat."] = "Handler på dine vegne: afviser duelanmodninger fra folk der ikke er dine venner, uden for kamp.",
	["Acts for you: declines group invites from people who aren't your friends, out of combat."] = "Handler på dine vegne: afviser gruppeinvitationer fra folk der ikke er dine venner, uden for kamp.",
	["Acts for you: declines guild invites from anyone but your friends, out of combat."] = "Handler på dine vegne: afviser guildinvitationer fra alle andre end dine venner, uden for kamp.",
	["Acts for you: declines quests shared by people who aren't your friends, out of combat."] = "Handler på dine vegne: afviser quests delt af folk der ikke er dine venner, uden for kamp.",
	["Acts for you: declines requests to join your group from people who aren't your friends, out of combat."] = "Handler på dine vegne: afviser anmodninger om at blive med i din gruppe fra folk der ikke er dine venner, uden for kamp.",
	["Acts for you: hands in finished quests and stops when there is a reward to choose, so you always pick it."] = "Handler på dine vegne: afleverer færdige quests og stopper når der er en belønning at vælge, så du altid selv vælger den.",
	["Acts for you: repairs all gear when you open a vendor who can repair."] = "Handler på dine vegne: reparerer alt udstyr når du åbner en købmand der kan reparere.",
	["Acts for you: sells gray items when you open a vendor, in batches of 12. Only the last 12 sold stacks stay in the buyback tab."] = "Handler på dine vegne. Sælger grå genstande når du åbner en købmand, i hold på 12. Tilbagekøbsfanen rummer kun de sidste 12 solgte stakke.",
	["Acts for you: skips a cutscene or movie you already watched on any character."] = "Handler på dine vegne: springer en cutscene eller film over som du allerede har set på en af dine karakterer.",
	["Acts for you: the word the game asks for before you destroy a rare item or a quest item is typed in. You still press Yes yourself."] = "Handler på dine vegne: ordet spillet beder om før du ødelægger en sjælden genstand eller en questgenstand, bliver skrevet ind. Du trykker stadig selv på Yes.",
	["Acts for you: when an NPC only has a shop and no quest for you, the shop opens at once."] = "Handler på dine vegne: når en NPC kun har en butik og ingen quest til dig, åbner butikken med det samme.",
	["Acts for you: when you enter the world, a dungeon, a raid or a battleground, the totem bar switches to the loadout you picked for it, out of combat."] = "Handler på dine vegne: når du kommer ind i verden, et dungeon, et raid eller en battleground, skifter totemlinjen til det loadout du har valgt til det, uden for kamp.",
	["Add"] = "Tilføj",
	["Add a button by name"] = "Tilføj en knap efter navn",
	["Add a cut..."] = "Tilføj en andel ...",
	["add a note"] = "tilføj en note",
	["Add a player..."] = "Tilføj en spiller ...",
	["add a rank"] = "tilføj en rang",
	["Add a spell ID"] = "Tilføj et evne-ID",
	["Add a waypoint"] = "Tilføj et waypoint",
	["Add a waypoint with /way 45 63 Goldshire or Ctrl-right-click on the world map. /way list opens the Waypoints window."] = "Tilføj et waypoint med /way 45 63 Goldshire eller Ctrl-højreklik på verdenskortet. /way list åbner Waypoints-vinduet.",
	["Add all"] = "Tilføj alle",
	["Add an empty rule at the end of the list."] = "Tilføj en tom regel sidst på listen.",
	["Add an entry"] = "Tilføj et punkt",
	["Add an extra text to this frame and edit it below."] = "Tilføj en ekstra tekst til rammen, og rediger den herunder.",
	["add as %q"] = "tilføj som %q",
	["Add each sale above: the item, who bought it and for how much gold."] = "Tilføj hvert salg ovenfor: genstanden, hvem der købte den, og for hvor meget guld.",
	["Add friend"] = "Tilføj ven",
	["Add friends after combat."] = "Tilføj venner efter kamp.",
	["Add missing macros"] = "Tilføj manglende makroer",
	["Add note"] = "Tilføj note",
	["Add note and mark entries to a player's right-click menu."] = "Tilføj punkterne for note og markering i en spillers højreklikmenu.",
	["Add one with /way 45 63 or Ctrl+right-click on the world map."] = "Tilføj et med /way 45 63 eller Ctrl+højreklik på verdenskortet.",
	["Add sale"] = "Tilføj salg",
	["Add text"] = "Tilføj tekst",
	["Add the same checks to the world map's own filter menu. Needs the World Map element switch (Blizzard UI page)."] = "Tilføj de samme flueben til verdenskortets egen filtermenu. Kræver elementkontakten Verdenskort (siden Blizzard-UI).",
	["Add the tag under a new quest's link, and tint new quests' titles where a tooltip lists them (quest mobs). Follows the Tooltips Blizzard UI setting."] = "Tilføj mærket under linket til en ny quest, og farv titlerne på nye quests hvor en tooltip viser dem (questmobs). Følger indstillingen Tooltips i Blizzard-UI.",
	["Add this ready-made rule at the end of the list. Change it like any other rule."] = "Tilføj denne færdige regel sidst på listen. Ret den som enhver anden regel.",
	["Add to bench"] = "Sæt på bænken",
	["Add to priority list"] = "Føj til prioritetslisten",
	["Add to the ledger"] = "Tilføj til regnskabet",
	["Add to this menu"] = "Føj til denne menu",
	["Add your current standing with the faction."] = "Tilføj dit nuværende omdømmetrin hos fraktionen.",
	["Added by a plugin through the unit frames."] = "Tilføjet af et plugin gennem unitframes.",
	["Addon button bin"] = "Samlekasse til addonknapper",
	["Addon buttons"] = "Addonknapper",
	["Addon buttons per row in the bin."] = "Addonknapper pr. række i samlekassen.",
	["Addon compartment"] = "Addonmenu",
	["Addon menu entry"] = "Punkt i addonmenuen",
	["Address book"] = "Adressebog",
	["Address book button"] = "Adressebogsknap",
	["Adds a ready-made rule at the end of the list: enemy totems show as an orange name above other plates. It stands down in dungeons and raids."] = "Tilføjer en færdig regel sidst på listen: fjendtlige totems vises som et orange navn over andre nameplates. Den holder pause i dungeons og raids.",
	["Adds a ready-made rule at the end of the list: your group's totems show as a small name. Needs friendly minion plates (Game settings tab); stands down in instances."] = "Tilføjer en færdig regel sidst på listen: din gruppes totems vises som et lille navn. Kræver nameplates for venlige minions (fanen Spilindstillinger); holder pause i instanser.",
	["Adds a Share mine button that sends your lowest durability and EldoUI version to the group once per ready check, for their report. Nothing is sent without your click."] = "Tilføjer en Del mine-knap som sender din laveste holdbarhed og EldoUI-version til gruppen én gang pr. klar-tjek til deres rapport. Intet sendes uden dit klik.",
	["Adds damage or healing per second and per mana under a spell's tooltip, read from the tooltip's own text. English and German clients."] = "Tilføjer skade eller healing pr. sekund og pr. mana under en evnes tooltip, læst fra tooltippens egen tekst. Engelske og tyske klienter.",
	["Adds Guild invite when you can invite the player, and Who to look up their character by name."] = "Tilføjer Invitér til guild når du kan invitere spilleren, og Spillersøgning til at slå karakteren op efter navn.",
	["Adds missing reagents for the selected number of crafts to the Profession Planner shopping list. Nothing is bought or crafted."] = "Føjer manglende reagenser til det valgte antal crafts til fagplanlæggerens indkøbsliste. Intet købes eller craftes.",
	["Adds Planner, Import build and, for classes with suggested paths, Recommended build to Blizzard's talent page. They only save plans; nothing is learned."] = "Tilføjer Planlægger, Importer build og, for klasser med foreslåede stier, Anbefalet build til Blizzards talentside. De gemmer kun planer; intet bliver lært.",
	["Adds the character macro EldoUI Rares that presses the targeting key, to put on an action bar. Your own macros are never changed."] = "Tilføjer karaktermakroen EldoUI Rares som trykker på målvalgstasten, så du kan sætte den på en handlingslinje. Dine egne makroer ændres aldrig.",
	["Adds the item, the buyer and the price to the ledger."] = "Tilføjer genstanden, køberen og prisen til regnskabet.",
	["Adds the items' worth at your saved auction prices (needs the Auction House module). \"+?\" means some items have no saved price."] = "Lægger genstandenes værdi sammen ud fra dine gemte auktionspriser (kræver modulet Auktionshus). \"+?\" betyder at nogle genstande ikke har en gemt pris.",
	["Adds the line under each group loot roll, on EldoUI's roll bars and on Blizzard's roll frames."] = "Tilføjer linjen under hvert lootrul i gruppen, på EldoUI's rulbjælker og på Blizzards rulrammer.",
	["Adds the realm after characters from another realm."] = "Tilføjer realm efter karakterer fra en anden realm.",
	["Adds the spell ID to spell tooltips in the spellbook and talents. The Tooltip module's own Spell ID line takes over when it shows one."] = "Tilføjer evne-ID'et til evnetooltips i evnebogen og talenterne. Tooltip-modulets egen linje Evne-ID tager over når den viser et.",
	["Adds the SR and TMB lines to item tooltips. The Tooltip module's section list can also turn them off."] = "Tilføjer SR- og TMB-linjerne til tooltips for genstande. Tooltip-modulets afsnitsliste kan også slå dem fra.",
	["Adds the zone you are in now to the quiet zones. The card menu offers it for the rare's zone too."] = "Føjer den zone du er i nu til de stille zoner. Kortets menu tilbyder det også for rarens zone.",
	["Adds this player to your WoW friends list."] = "Tilføjer denne spiller til din WoW-venneliste.",
	["Adds this recipe to the Profession Planner's shopping list with a number of crafts. Nothing is crafted."] = "Tilføjer denne opskrift til fagplanlæggerens indkøbsliste med et antal crafts. Der bliver ikke craftet noget.",
	["Adds three sample rows to the feed (/eui notify test pings)."] = "Tilføjer tre eksempelrækker til feedet (/eui notify test pings).",
	["Advanced"] = "Avanceret",
	["Advanced settings"] = "Avancerede indstillinger",
	["Adventure guide"] = "Eventyrguide",
