	["Affordable only"] = "Kun dem du har råd til",
	["After a ready check, one line in chat with who wasn't ready or didn't answer."] = "Efter et klar-tjek kommer én linje i chatten med hvem der ikke var klar eller ikke svarede.",
	["After a ready check, one line in your own chat window with who is ready, who said not ready, who never answered and who is offline. Only you see it; Post to group sends it."] = "Efter et klar-tjek en linje i dit eget chatvindue med hvem der er klar, hvem der svarede ikke klar, hvem der aldrig svarede og hvem der er offline. Kun du ser den; Del i gruppen sender den.",
	["After a trade that moved gold, one line in chat (only you see it), such as \"Gave 5g to Name\", with a link to the log."] = "Efter en handel der flyttede guld, kommer én linje i chatten (kun du ser den), fx \"Gav 5g til Navn\", med et link til loggen.",
	["After arriving or removing one, the arrow points at the closest waypoint left."] = "Når du er ankommet eller har fjernet et, peger pilen på det nærmeste waypoint der er tilbage.",
	["After combat."] = "Efter kampen.",
	["After the helper takes one quest from an NPC, their other quests wait until you talk to them again."] = "Når hjælperen har taget én quest fra en NPC, venter NPC'ens andre quests til du taler med den igen.",
	["After you release your spirit, a waypoint on your corpse (the arrow points there). It goes away when you are alive again."] = "Når du har frigivet din ånd, sættes et waypoint på dit lig (pilen peger derhen). Det forsvinder når du er i live igen.",
	["After you zoom with the mouse wheel, the map zooms back out after this many seconds. 0 keeps your zoom."] = "Når du har zoomet med musehjulet, zoomer kortet ud igen efter så mange sekunder. 0 beholder din zoom.",
	["AH %s"] = "AH %s",
	["Air"] = "Luft",
	["Alert again after"] = "Advar igen efter",
	["Alert again for all %d ignored rares?"] = "Advar igen for alle %d ignorerede rares?",
	["Alert again for every rare you chose to ignore (card menu: Ignore this rare)."] = "Advar igen for alle rares du har valgt at ignorere (kortmenuen: Ignorer denne rare).",
	["Alert Lane"] = "Advarselsbane",
	["Alert lane"] = "Advarselsbane",
	["Alert outdoors when you see an opposing player after three confirmed kills in either direction. Off by default."] = "Vis en advarsel udendørs når du ser en spiller fra den modsatte fraktion efter tre bekræftede drab den ene eller den anden vej. Slået fra som standard.",
	["Alerts"] = "Advarsler",
	["Alerts and Banners"] = "Advarsler og bannere",
	["Alerts grow up from their mover, for a lane near the bottom of the screen."] = "Advarsler vokser opad fra deres flyttefelt, til en bane nær bunden af skærmen.",
	["Alerts growing down, normal sizes and times."] = "Advarsler der vokser nedad, normale størrelser og tider.",
	["Alerts sit on the \"Alert Lane\" mover, level-up toasts and boss banners on \"Banners\", Battle.net toasts and the GM ticket on \"Battle.net Toasts\"."] = "Advarsler sidder på flyttefeltet \"Advarselsbane\", pop op-beskeder om nyt level og bossbannere på \"Bannere og nyt level\", Battle.net-pop op-beskeder og GM-ticketten på \"Pop op-beskeder fra Battle.net\".",
	["Alias removed."] = "Alias fjernet.",
