	["Aliases"] = "Aliasser",
	["Aliases in place of real character names on EldoUI's frames, tooltips and chat while you stream or record."] = "Aliasser i stedet for rigtige karakternavne på EldoUI's rammer, tooltips og chat mens du streamer eller optager.",
