	["All values in one line; off gives each value its own row."] = "Alle værdier på én linje. Slået fra får hver værdi sin egen række.",
	["All zone text, or only the subzone (the zone name still shows when you enter a new zone)."] = "Al zonetekst eller kun underzonen (zonenavnet vises stadig når du kommer ind i en ny zone).",
	["Alliance, Horde or free-for-all badge by the name."] = "Mærke for Alliance, Horde eller free-for-all ved navnet.",
	["Allow posting"] = "Tillad at lægge op i chatten",
	["Allow this demon. With it off, having it out counts as the wrong demon; the first allowed demon is the one a click summons."] = "Tillad denne dæmon. Uden flueben tæller den som den forkerte dæmon når den er fremme; den første tilladte dæmon er den som et klik tilkalder.",
	["already active"] = "allerede aktivt",
	["Already done"] = "Allerede klaret",
	["Already known"] = "Allerede kendt",
	["Also /eui in chat."] = "Også /eui i chatten.",
	["Also alert for a rare that is already dead."] = "Advar også for en rare der allerede er død.",
	["Also alert for world bosses such as Azuregos."] = "Advar også for verdensbosser som Azuregos.",
	["Also alert inside instances. Most names are hidden there, so few rares show."] = "Advar også inde i instanser. Der er de fleste navne skjult, så kun få rares vises.",
	["Also alert while you are on a flight path."] = "Advar også mens du er på en flyverute.",
	["Also counts the reagent on your other characters, from the Bags module's inventory list."] = "Tæller også reagenset på dine andre karakterer, ud fra beholdningslisten i modulet Tasker.",
	["Also debug and GM settings, and the ones the game locks or shows read-only."] = "Også debug- og GM-indstillinger og dem som spillet låser eller viser som skrivebeskyttede.",
	["Also from nameplates"] = "Også fra nameplates",
	["Also in combat"] = "Også i kamp",
	["Also in parties"] = "Også i grupper",
	["Also list skills you have already learned."] = "Vis også evner du allerede har lært.",
	["Also offer the item of a quest that is ready to turn in."] = "Tilbyd også genstanden fra en quest der er klar til at blive afleveret.",
	["Also on continent maps"] = "Også på kontinentkort",
	["Also on the focus cast bar"] = "Også på fokusets castbar",
	["Also opens the window with /wt, unless another addon uses /wt."] = "Åbner også vinduet med /wt, medmindre en anden addon bruger /wt.",
	["Also remember casts of mobs that only show a nameplate."] = "Husk også casts fra mobs der kun viser en nameplate.",
	["Also seen here"] = "Også set her",
	["Also set the game's own map pin and tracking on the waypoint the arrow points at."] = "Sæt også spillets egen kortnål og sporing på det waypoint pilen peger på.",
	["Also show flight masters you have not talked to, grayed, so you can go and learn them."] = "Vis også flyvemestre du ikke har talt med, nedtonet, så du kan tage hen og lære dem.",
	["Also show this note on the continent map (Kalimdor, Eastern Kingdoms)."] = "Vis også denne note på kontinentkortet (Kalimdor, Eastern Kingdoms).",
	["Also show while"] = "Vis også mens",
	["Also sliders for effects, music, ambience and dialog."] = "Også skydere til effekter, musik, omgivelser og dialog.",
	["Also turns off the game's full-screen glow setting. On by default when Disable screen effects is on."] = "Slår også spillets fuldskærmsglød fra. Til som standard når Slå skærmeffekter fra er slået til.",
	["Also watch for these names"] = "Hold også øje med disse navne",
	["Alt+right-click adds a note"] = "Alt+højreklik tilføjer en note",
	["Alt+Shift"] = "Alt+Shift",
	["Alt+Shift-click attaches every stack of that item."] = "Alt+Shift-klik vedhæfter alle stakke af den genstand.",
	["Alt-click a bag item to attach it"] = "Alt-klik på en genstand i tasken for at vedhæfte den",
	["Alt-click a vendor item to add it"] = "Alt-klik på en købmandsgenstand for at tilføje den",
	["Alt-click an item in the merchant window to put it on the restock list with one stack."] = "Alt-klik på en genstand i købmandsvinduet for at sætte den på genopfyldningslisten med én stak.",
	["Always compare items"] = "Sammenlign altid genstande",
	["Always gray"] = "Altid grå",
	["Always sell"] = "Sælg altid",
	["Always sharpen"] = "Skærp altid",
	["Always show plates"] = "Vis altid nameplates",
	["Always the faction"] = "Altid fraktionen",
	["Always, or only while the mouse is over the bars."] = "Altid eller kun mens musen er over bjælkerne.",
	["Ambience"] = "Omgivelser",
	["Ammo (hunters)"] = "Ammunition (Hunters)",
	["Ammo without a quiver"] = "Ammunition uden kogger",
	["amount"] = "antal",
	["An \"Abilities seen\" row on a hostile mob's tooltip, from what the log remembered. Hold Shift to see all of them."] = "En række \"Evner set\" i en fjendtlig mobs tooltip ud fra det loggen har husket. Hold Shift nede for at se dem alle.",
	["An alert card when your shield is running out or gone. The game doesn't tell addons about your auras in combat, so this one waits until the fight ends."] = "Et advarselskort når dit skjold er ved at løbe ud eller er væk. Spillet fortæller ikke addons om dine auraer i kamp, så denne venter til kampen er slut.",
	["An anvil when your most worn item reaches Worn gear on the General page (yellow), red once it is low, so you repair in time. Shown in rest areas too."] = "En ambolt når din mest slidte genstand rammer grænsen \"Slidt udstyr ved\" på siden Generelt (gul), og rød når den er lav, så du reparerer i tide. Vises også i hvileområder.",
	["An arrow that points at the current waypoint, with its distance and arrival time."] = "En pil der peger på det aktuelle waypoint med afstand og ankomsttid.",
	["An EldoUI button in the game menu: click opens the EldoUI settings, right-click starts move mode. With Blizzard UI > Game menu (Esc) on, it sits right above AddOns."] = "En EldoUI-knap i spilmenuen: klik åbner EldoUI-indstillingerne, højreklik starter flyttetilstand. Med Blizzard-UI > Spilmenu (Esc) slået til sidder den lige over AddOns.",
	["An entry in the addon compartment menu by the minimap that opens the window."] = "Et punkt i addonmenuen ved minikortet som åbner vinduet.",
	["An icon over the object or character you would interact with next (game setting SoftTargetIconInteract)."] = "Et ikon over den ting eller karakter du vil interagere med som det næste (spilindstillingen SoftTargetIconInteract).",
	["An icon when this unit is in another phase."] = "Et ikon når enheden er i en anden fase.",
	["An icon while a resurrection is on its way to this unit."] = "Et ikon mens en genoplivning er på vej til enheden.",
	["An item's enchant adds its plain stats (+7 Agility) to its score. Off compares items bare, as a new item would be before you enchant it. Procs are never counted."] = "En genstands enchant lægger sine rene stats (+7 Agility) til dens score. Når den er slået fra, sammenlignes genstandene uden enchant, ligesom en ny genstand før du enchanter den. Procs tælles aldrig med.",
	["An objective's count (3/8) sits at the right end of its line in the accent color. Lines too long for both keep Blizzard's text."] = "Tælleren for et mål (3/8) står yderst til højre på linjen i accentfarven. Linjer der er for lange til begge dele, beholder Blizzards tekst.",
	["An over-the-shoulder view. It uses the game's experimental camera settings: the game asks you once to confirm them, and Disable there turns ActionCam off. Off puts your own values back."] = "En visning over skulderen. Den bruger spillets eksperimentelle kameraindstillinger: spillet beder dig bekræfte dem én gang, og Disable dér slår ActionCam fra. Når den er slået fra, får du dine egne værdier tilbage.",
	["An upright column of large buttons."] = "En lodret kolonne med store knapper.",
	["Animation"] = "Animation",
	["Ankh %d"] = "Ankh %d",
	["announce the last reset to the group (Instances > Resets > Announce reset)"] = "meld den seneste reset til gruppen (Instanser > Resets > Meld reset)",
	["Anonymous"] = "Anonymous",
	["Another action in progress"] = "En anden handling er i gang",
	["Another addon gathers the minimap buttons: %s."] = "En anden addon samler minikortknapperne: %s.",
	["Another character, or Best of all: the best time per level over all your other characters."] = "En anden karakter, eller Bedste af alle: den bedste tid pr. level på tværs af alle dine andre karakterer.",
	["Answers hop requests from your guild and, while you are in the layer network, from its players. Each request shows a card: Invite or Not now. Never in combat or in an instance."] = "Svarer på hop-forespørgsler fra din guild og fra layer-netværkets spillere mens du er i det. Hver forespørgsel viser et kort: Inviter eller Ikke nu. Aldrig i kamp eller i en instans.",
	["Answers in chat"] = "Svar i chatten",
	["Any alert type not listed here."] = "Alle advarselstyper der ikke står her.",
	["Any buff by spell ID: the reminder shows while no rank of it is on you. A tooltip addon or database site shows spell IDs."] = "Enhver buff efter evne-ID: påmindelsen vises så længe ingen rang af den er på dig. En tooltip-addon eller en databaseside viser evne-ID'er.",
	["Any number of extra texts made of tags, placed anywhere on the frame."] = "Et vilkårligt antal ekstra tekster lavet af tags, placeret hvor som helst på rammen.",
	["Any paladin blessing, single or greater."] = "Enhver Paladin-blessing, almindelig eller Greater.",
	["Any quality"] = "Enhver kvalitet",
	["Appearance unavailable"] = "Udseende utilgængeligt",
	["Apply the nameplate style your layout names (Layouts page). Your other settings stay."] = "Anvend den nameplatestil som dit layout angiver (siden Layouts). Dine andre indstillinger bevares.",
	["Arcane Intellect or Arcane Brilliance."] = "Arcane Intellect eller Arcane Brilliance.",
