	["Art style"] = "Grafikstil",
	["Art style follows EldoUI's art style. Game icons always use the game's map icons. Dots are small dots in the loot's quality color. Loot icons show the best drop."] = "Grafikstil følger EldoUI's grafikstil. Spilikoner bruger altid spillets egne kortikoner. Prikker er små prikker i lootets kvalitetsfarve. Lootikoner viser det bedste drop.",
