	["food"] = "mad",
	["Food buff"] = "Madbuff",
	["For \"XP, reputation and honor bars\" in Blizzard UI with Skin or Move. Their width and height stay in Edit Mode."] = "For \"XP-, omdømme- og ærebjælker\" i Blizzard-UI med Skin eller Flyt. Bredden og højden styres stadig i Edit Mode.",
	["For 30 minutes"] = "I 30 minutter",
	["For Blizzard's bag bar, once it is on in Blizzard UI. Move and scale gives it a mover; Replace docks the bag buttons on EldoUI's bag window."] = "Til Blizzards taskelinje når den er slået til i Blizzard-UI. Flyt og skaler giver den et flyttefelt; Erstat placerer taskeknapperne på EldoUI's taskevindue.",
	["For Blizzard's micro menu, once it is on in Blizzard UI. Move and scale gives it a mover; Replace puts a Menu block on the Info Bar."] = "Til Blizzards mikromenu når den er slået til i Blizzard-UI. Flyt og skaler giver den et flyttefelt; Erstat sætter en Menu-blok på infobjælken.",
	["For camping a spawn: loud repeating sound, cards stay until closed, three at once (they grow down over the alert lane)."] = "Til at campe et spawn: høj gentaget lyd, kort bliver indtil de lukkes, tre ad gangen (de vokser nedad over advarselsbanen).",
	["For group buffs (Fortitude, Intellect, Mark of the Wild), count group members without it, when the game lets addons read their auras."] = "For gruppebuffs (Fortitude, Intellect, Mark of the Wild) tælles gruppemedlemmer uden den når spillet lader addons læse deres auraer.",
	["For hunters: a Feed Pet button by the pet frame; one click feeds one piece of food. The [pet:happiness] tag shows happiness."] = "Til Hunters: en Feed Pet-knap ved petrammen; ét klik fodrer med ét stykke mad. Tagget [pet:happiness] viser tilfredsheden.",
	["For quest"] = "Til quest",
	["For tanks (the role you picked in setup): remind me when this buff is missing, running out or a higher rank is known."] = "Til tanks (rollen du valgte i opsætningen): påmind mig når denne buff mangler, er ved at løbe ud eller en højere rang er kendt.",
	["For tanks (the role you picked in setup): remind me when you know this stance or form and are not in it. A click takes it."] = "Til tanks (rollen du valgte i opsætningen): påmind mig når du kender denne stance eller form og ikke er i den. Et klik skifter til den.",
	["For tanks (the role you picked in setup): remind me when your off hand holds no shield."] = "Til tanks (rollen du valgte i opsætningen): påmind mig når din off hand ikke holder et skjold.",
	["For your %s. Sold by the demon trainer's vendor."] = "Til din %s. Sælges af dæmontrænerens købmand.",
	["Forever's day and night cycle as a small icon on the map."] = "Forevers dag- og natcyklus som et lille ikon på kortet.",
	["Forever's keyring button next to the bags (when the game offers it)."] = "Forevers nøgleringsknap ved siden af taskerne (når spillet har den).",
	["forget  play every cutscene again once (skip seen cutscenes)"] = "forget  afspil hver cutscene igen én gang (spring sete cutscenes over)",
