	["Herbalism and mining"] = "Herbalism og Mining",
	["Here: %d action slots, %d macros and %d keys would change."] = "Her: %d handlingspladser, %d makroer og %d taster ville blive ændret.",
	["Hidden buttons still work through their keybinds and the Info Bar Menu block."] = "Skjulte knapper virker stadig via deres genvejstaster og Menu-blokken på infobjælken.",
	["Hidden map points are shown again."] = "Skjulte kortpunkter vises igen.",
	["Hidden settings: camera"] = "Skjulte indstillinger: kamera",
	["Hidden settings: chat"] = "Skjulte indstillinger: chat",
	["Hidden settings: floating combat text"] = "Skjulte indstillinger: flydende kamptekst",
	["Hidden settings: graphics"] = "Skjulte indstillinger: grafik",
	["Hidden when the game keeps the target secret."] = "Skjult når spillet holder målet hemmeligt.",
	["Hidden widgets take game information with them (battleground scores, capture bars)."] = "Skjulte widgets tager spilinformation med sig (battleground-score, erobringsbjælker).",
	["Hide \"Made by\""] = "Skjul \"Made by\"",
	["Hide \"Screen captured\""] = "Skjul \"Screen captured\"",
	["Hide \"screenshot saved\""] = "Skjul \"skærmbillede gemt\"",
	["Hide a rare or treasure when its quest is done, or when it drops a mount, pet or toy and you have all of them. Points with neither, like most Classic rares, always show."] = "Skjul en rare eller skat når dens quest er klaret, eller når den dropper en mount, et pet eller et toy, og du har dem alle. Punkter uden nogen af delene (fx de fleste Classic-rares) vises altid.",
	["Hide all player names"] = "Skjul alle spillernavne",
	["Hide at max level"] = "Skjul ved maks. level",
	["Hide at the level cap"] = "Skjul ved levelgrænsen",
	["Hide below-minimap widgets"] = "Skjul widgets under minikortet",
	["Hide Blizzard's totem bar"] = "Skjul Blizzards totemlinje",
	["Hide casts you can't interrupt"] = "Skjul casts der ikke kan afbrydes",
	["Hide click hints"] = "Skjul klikhjælp",
	["Hide completed"] = "Skjul klarede",
	["Hide drunken messages"] = "Skjul beskeder om fuldskab",
	["Hide duel results"] = "Skjul duelresultater",
	["Hide enemy plates out of combat and show them when combat starts. While this is on it decides \"Enemy plates\" below, which is grayed out."] = "Skjul fjendtlige nameplates uden for kamp, og vis dem når kampen starter. Mens dette er slået til, bestemmer det \"Fjendtlige nameplates\" nedenfor som er nedtonet.",
	["Hide finished reagents"] = "Skjul færdige reagenser",
	["Hide for NPCs"] = "Skjul for NPC'er",
	["Hide in combat"] = "Skjul i kamp",
	["Hide in instances"] = "Skjul i instanser",
	["Hide in raids"] = "Skjul i raids",
	["Hide it completely (no voice), or hide only the frame and still hear the voice."] = "Skjul den helt (ingen stemme), eller skjul kun rammen og hør stadig stemmen.",
	["Hide items below this quality."] = "Skjul genstande under denne kvalitet.",
	["Hide out of combat"] = "Skjul uden for kamp",
	["Hide plates behind the camera"] = "Skjul nameplates bag kameraet",
	["Hide red errors by category, in combat, or always. Yellow quest progress always shows."] = "Skjul røde fejl efter kategori, i kamp eller altid. Gult questfremskridt vises altid.",
	["Hide the alert types checked below."] = "Skjul advarselstyperne med flueben nedenfor.",
	["Hide the arrow"] = "Skjul pilen",
	["Hide the bar for spells the game does not mark as important, so only the casts that matter show."] = "Skjul bjælken for evner som spillet ikke markerer som vigtige, så kun de casts der betyder noget, vises.",
	["Hide the encounter bar"] = "Skjul encounter-bjælken",
	["Hide the faction line"] = "Skjul fraktionslinjen",
	["Hide the four bag slots; the backpack button stays."] = "Skjul de fire taskepladser; rygsækknappen bliver.",
	["Hide the game's own totem bar and totem timers while this bar is on, so there is one totem bar."] = "Skjul spillets egen totemlinje og totemnedtællinger mens denne linje er slået til, så der kun er én totemlinje.",
	["Hide the large map when combat starts and return it to its normal position after combat."] = "Skjuler det store minikort ved kampstart og sætter det tilbage på sin plads efter kampen.",
	["hide the list"] = "skjul listen",
	["Hide the other faction's flight masters, docks and towers. Neutral ones always show."] = "Skjul den anden fraktions flyvemestre, havne og tårne. Neutrale vises altid.",
	["Hide the other faction's services. Neutral towns, and NPCs whose side the data can't tell, always show."] = "Skjul den anden fraktions tjenester. Neutrale byer og NPC'er hvis side dataene ikke kan afgøre, vises altid.",
	["Hide the plate"] = "Skjul nameplaten",
	["Hide the PvP line"] = "Skjul PvP-linjen",
	["Hide the Shop micro button"] = "Skjul butikkens mikroknap",
	["Hide them"] = "Skjul dem",
	["Hide these types"] = "Skjul disse typer",
	["Hide this point"] = "Skjul dette punkt",
	["Hide top-center widgets"] = "Skjul widgets øverst i midten",
	["Hide what"] = "Hvad skjules",
	["Hide what you already know"] = "Skjul det du allerede kender",
	["Hide your own and friendly names"] = "Skjul dit eget navn og venlige spilleres navne",
	["Hide: %s"] = "Skjul: %s",
	["Hides \"X has defeated Y in a duel\" system messages."] = "Skjuler systembeskeder af typen \"X has defeated Y in a duel\".",
	["Hides <Right Click to Open>, <Right Click to Read> and <Shift Right Click to Socket>."] = "Skjuler <Right Click to Open>, <Right Click to Read> og <Shift Right Click to Socket>.",
	["Hides Blizzard's own item level line while the info area shows it, so it appears once."] = "Skjuler Blizzards egen item level-linje mens infoområdet viser den, så den kun vises én gang.",
	["Hides names in what EldoUI draws: unit, group and nameplate texts, tooltips and chat senders. Other frames keep the real names."] = "Skjuler navne i det EldoUI tegner: unit-, gruppe- og nameplatetekster, tooltips og chatafsendere. Andre rammer beholder de rigtige navne.",
	["Hides other players' \"X seems a little tipsy\" messages."] = "Skjuler beskeder af typen \"X seems a little tipsy\" om andre spillere.",
	["Hides the bar while the cast can't be interrupted."] = "Skjuler bjælken mens castet ikke kan afbrydes.",
	["Hides the crafter and gift-wrap lines (matched by the game's own text)."] = "Skjuler linjerne \"Made by\" og gaveindpakning (genkendt på spillets egen tekst).",
	["Hides the names over characters in the world through the game's own name settings while Streamer Mode is on, and puts your settings back when it goes off. Off by default (Game setting)."] = "Skjuler navnene over karakterer i spilverdenen via spillets egne navneindstillinger mens Streamertilstand er slået til, og sætter dine indstillinger tilbage når den slås fra. Slået fra som standard (Spillets indstilling).",
	["Higher in the list: this rule wins over the ones below."] = "Højere på listen: denne regel har forrang for dem nedenfor.",
	["Higher rank known"] = "Højere rang kendt",
	["Higher rank known (%d > %d)"] = "Højere rang kendt (%d > %d)",
	["Higher rank known (preview)"] = "Højere rang kendt (forhåndsvisning)",
	["Higher zooms faster; the game's default is 20 (game setting)."] = "Højere zoomer hurtigere; spillets standard er 20 (spilindstilling).",
	["Highest known rank"] = "Højeste kendte rang",
	["Highest unit level."] = "Det højeste level enheden må have.",
	["Highlight in the accent color"] = "Fremhæv i accentfarven",
	["Highlight your name"] = "Fremhæv dit navn",
	["Highlight your soft target"] = "Fremhæv dit soft target",
	["History"] = "Historik",
	["History browser"] = "Historikoversigt",
	["History days to keep"] = "Dage historikken skal gemmes",
	["History entries to keep"] = "Antal gemte historiklinjer",
	["History options"] = "Historikindstillinger",
	["Hold %s to compare with the rank you know"] = "Hold %s-tasten nede for at sammenligne med den evnerang du kender",
	["Hold a key for a ring, fan or grid of your own spells, items, macros, mounts and markers; let go on one to use it."] = "Hold en tast nede for en ring, vifte eller et gitter med dine egne evner, genstande, makroer, mounts og markører; slip på én for at bruge den.",
	["Hold a menu's key to show its entries around the cursor; point at one and let go to use it. Escape cancels. Works in combat."] = "Hold en menus tast nede for at vise dens punkter rundt om markøren; peg på et, og slip for at bruge det. Escape annullerer. Virker i kamp.",
	["Hold Alt and right-click on the world map to add your own note there. While HandyNotes is loaded, its own Alt+right-click is used instead."] = "Hold Alt nede, og højreklik på verdenskortet for at tilføje din egen note der. Når HandyNotes er indlæst, bruges dens eget Alt+højreklik i stedet.",
	["Hold both modifiers and right-click an item in EldoUI bags or bank. Gray items toggle Never sell, other items toggle Always sell. Protected items stay unchanged."] = "Hold begge taster nede, og højreklik på en genstand i EldoUI-tasker eller banken. Grå genstande skifter Sælg aldrig, andre skifter Sælg altid. Beskyttede genstande ændres ikke.",
	["Hold Ctrl and right-click on the world map to add a waypoint there."] = "Hold Ctrl nede, og højreklik på verdenskortet for at tilføje et waypoint der.",
	["Hold Shift for node types"] = "Hold Shift for nodetyper",
	["Hold Shift over a zone to list its herbs and ore veins: your own finds when the Gathering module knows the zone, else the nodes that typically grow there."] = "Hold Shift over en zone for at se dens urter og malmårer: dine egne fund når modulet Indsamling kender zonen, ellers de nodes der typisk findes der.",
	["Hold Shift to see what the values come from: the average, the part over time, the time used and the mana cost."] = "Hold Shift nede for at se hvad værdierne kommer fra: gennemsnittet, delen over tid, den brugte tid og manaprisen.",
	["Hold this key while casting a helpful spell to cast it on yourself (the game's key binding setting)."] = "Hold denne tast nede mens du caster en hjælpende evne, for at caste den på dig selv (spillets indstilling for genvejstaster).",
	["Hold this key while talking to an NPC to stop the quest helpers."] = "Hold denne tast nede mens du taler med en NPC, for at stoppe questhjælperne.",
	["Hold time"] = "Visningstid",
	["Hold to pause"] = "Hold nede for pause",
	["Hold to show in combat"] = "Hold for at vise i kamp",
	["Holding this key shows hidden tooltips anyway."] = "Når du holder denne tast nede, vises skjulte tooltips alligevel.",
	["Holds the item of your tracked quest. Bind a key to it in keybind mode."] = "Rummer genstanden fra din sporede quest. Tildel den en tast i genvejstasttilstand.",
	["Honor bar"] = "Ærebjælke",
	["Honor color"] = "Ærefarve",
	["Hop canceled."] = "Hoppet er annulleret.",
	["hop to another layer"] = "hop til et andet layer",
	["Hop to another layer"] = "Hop til et andet layer",
	["Hop to layer %s"] = "Hop til layer %s",
	["Hopping"] = "Hop",
	["Horizontal distance from the cursor."] = "Vandret afstand fra markøren.",
	["Horizontal shift from the frame's right edge."] = "Vandret forskydning fra rammens højre kant.",
	["Horizontal shift in pixels."] = "Vandret forskydning i pixels.",
	["Horizontal shift of a free icon."] = "Vandret forskydning af et frit ikon.",
	["Horizontal shift of the combat icon."] = "Vandret forskydning af kampikonet.",
	["Horizontal shift of the resting icon."] = "Vandret forskydning af hvileikonet.",
	["Horizontal shift of the stack count."] = "Vandret forskydning af stakantallet.",
	["Horizontal shift of the time."] = "Vandret forskydning af tiden.",
	["Horizontal shift."] = "Vandret forskydning.",
	["Hostile units, with own colors for nameplates."] = "Fjendtlige enheder, med egne farver til nameplates.",
	["Hostile, neutral and friendly"] = "Fjendtlige, neutrale og venlige",
	["HoT/s"] = "HoT/s",
	["Housing"] = "Housing",
	["Hover a cast bar for the spell's tooltip; a mob's tooltip lists the abilities it cast in front of you and where reputation tokens go."] = "Hold musen over en castbar for at se evnens tooltip; en mobs tooltip viser de evner den har castet foran dig, og hvor omdømmetokens skal hen.",
	["Hover a zone on a continent map for its level range, gathering ranges, dungeons and territory. Hold Shift for its node types."] = "Hold musen over en zone på et kontinentkort for at se levelinterval, indsamlingsintervaller, dungeons og territorium. Hold Shift for nodetyper.",
	["Hover an item, spell, quest or creature (or target a creature), then type /eui wowhead. Ctrl+Alt-click works on chat links."] = "Hold musen over en genstand, evne, quest eller et væsen (eller tag et væsen som mål), og skriv så /eui wowhead. Ctrl+Alt-klik virker på links i chatten.",
	["Hover any EldoUI button and press a key. Out of combat only."] = "Hold musen over en EldoUI-knap, og tryk på en tast. Kun uden for kamp.",
	["Hover one of EldoUI's cooldown icons and press your ping key: the game pings that spell or item, as it does for Blizzard's Cooldown Manager. One key press, one ping."] = "Hold musen over et af EldoUI's cooldown-ikoner, og tryk på din pingtast: spillet pinger den evne eller genstand, ligesom for Blizzards Cooldown Manager. Ét tastetryk, ét ping.",
	["Hover the quest item button and press a key, then click Save."] = "Hold musen over knappen til questgenstanden, tryk på en tast, og klik så på Gem.",
	["How a missing (red) reminder draws the eye. Glow uses the Reminders row on the Glows page."] = "Hvordan en manglende (rød) påmindelse fanger blikket. Glød bruger rækken Påmindelser på siden Glød.",
	["How close, in yards, counts as arrived."] = "Hvor tæt på du skal være (i yards) for at regnes som ankommet.",
	["How dark the panel is. 0.9 matches the game's own tooltips."] = "Hvor mørkt panelet er. 0,9 svarer til spillets egne tooltips.",
	["How dark the tooltip shadow is."] = "Hvor mørk tooltippens skygge er.",
	["How dark the world behind the flight view gets."] = "Hvor mørk verden bag flyvevisningen bliver.",
	["How detailed the volume fog is. Lower is faster."] = "Hvor detaljeret volumentågen er. Lavere er hurtigere.",
	["How early you can queue your next spell before the current cast or global cooldown ends (\"lag tolerance\"). Off keeps the game's value (now %s ms)."] = "Hvor tidligt du kan sætte din næste evne i kø før det nuværende cast eller den globale cooldown slutter (\"lag tolerance\"). Når den er slået fra, bruges spillets værdi (nu %s ms).",
	["How every gain in EldoUI is worked out for this character: your stat weights, or another rating mode an add-on provides (such as the Loot Guide's simulator)."] = "Hvordan alle gevinster i EldoUI udregnes for denne karakter: dine statvægte eller en anden vurderingsmetode som en addon leverer (fx simulatoren i Loot Guide).",
	["How far the camera can zoom out (game setting): now about %d yd. The range follows what this client allows."] = "Hvor langt kameraet kan zoome ud (spilindstilling): nu omkring %d yd. Rækkevidden følger det som denne klient tillader.",
	["How far the camera sits to the side of your character; below 0 is the left shoulder."] = "Hvor langt til siden for din karakter kameraet sidder; under 0 er venstre skulder.",
	["How far the tooltip shadow reaches beyond its edge."] = "Hvor langt tooltippens skygge rækker ud over kanten.",
	["How fast the camera tilts up and down when you drag with the mouse (game setting cameraPitchMoveSpeed)."] = "Hvor hurtigt kameraet hælder op og ned når du trækker med musen (spilindstillingen cameraPitchMoveSpeed).",
	["How fast the camera turns left and right when you drag with the mouse (game setting cameraYawMoveSpeed)."] = "Hvor hurtigt kameraet drejer til venstre og højre når du trækker med musen (spilindstillingen cameraYawMoveSpeed).",
	["How fast the numbers over targets fall after they appear. 0 lets them float (game setting WorldTextGravity)."] = "Hvor hurtigt tallene over mål falder når de er dukket op. 0 lader dem svæve (spilindstillingen WorldTextGravity).",
	["How high the frame sits among other bars. Raise it when another frame covers it. The game menu, the settings and popups always stay on top."] = "Hvor højt rammen ligger blandt andre bjælker. Hæv den når en anden ramme dækker den. Spilmenuen, indstillingerne og pop op-vinduer ligger altid øverst.",
	["How long a battleground message stays before it fades."] = "Hvor længe en battleground-besked bliver før den toner ud.",
	["How long a message stays; 0 keeps Blizzard's time."] = "Hvor længe en besked bliver; 0 beholder Blizzards tid.",
	["How long a toast stays. Hovering it keeps it; right-click closes it."] = "Hvor længe en pop op-besked bliver. Holder du musen over den, bliver den; højreklik lukker den.",
	["How long before the same rare alerts again."] = "Hvor længe der går før den samme rare giver en advarsel igen.",
	["How long the interrupted strip stays."] = "Hvor længe afbrydelsesstriben bliver.",
	["How long the panel stays open after the ready check ends."] = "Hvor længe panelet bliver åbent efter klar-tjekket er slut.",
	["How long until you arrive at your current speed towards it."] = "Hvor lang tid der går før du er fremme med din nuværende fart mod det.",
	["How many"] = "Antal",
	["How many %s? (sold in lots of %d)"] = "Hvor mange %s? (sælges %d ad gangen)",
	["How many abilities the row names before it shows (+N)."] = "Hvor mange evner rækken nævner før den viser (+N).",
	["How many automatic snapshots to keep per character; the oldest go first. Your own snapshots are kept (up to 20)."] = "Hvor mange automatiske øjebliksbilleder der gemmes pr. karakter; de ældste fjernes først. Dine egne øjebliksbilleder beholdes (op til 20).",
	["How many buttons before a new row starts."] = "Antal knapper før en ny række begynder.",
	["How many cells per row."] = "Hvor mange celler pr. række.",
	["How many conversations the dock shows. Right-click a dock button to close that conversation."] = "Hvor mange samtaler docken viser. Højreklik på en dock-knap for at lukke den samtale.",
	["How many lines of tiles before it scrolls. Columns times rows is how many items you see at once."] = "Hvor mange rækker af felter før der rulles. Kolonner gange rækker er hvor mange genstande du ser på én gang.",
	["How many mobs show before \"+N more\". Hold Shift for the full list."] = "Hvor mange mobs der vises før \"+N flere\". Hold Shift for hele listen.",
	["How many names a line lists before \"+N more\"."] = "Hvor mange navne en linje viser før \"+N flere\".",
	["How many of a reagent you have and need for the recipes you pinned in the Profession Planner."] = "Hvor mange af et reagens du har og skal bruge til de opskrifter du har fastgjort i fagplanlæggeren.",
	["How many of the chosen food you carry."] = "Hvor meget af den valgte mad du har på dig.",
	["How many of the item you carry, in the corner of its icon."] = "Hvor mange af genstanden du har på dig, i hjørnet af dens ikon.",
	["How many of the mob's most common drops to list."] = "Hvor mange af mobbens mest almindelige drops der vises.",
	["How many pings the feed shows; the newest is on top."] = "Hvor mange pings feedet viser; det nyeste er øverst.",
	["How many points the path plans, of the 51 a level 60 character has."] = "Hvor mange point stien planlægger, ud af de 51 en karakter på level 60 har.",
	["How many recipients the address book keeps under Recent."] = "Hvor mange modtagere adressebogen gemmer under Seneste.",
	["How many Runes of Teleportation and Runes of Portals you carry: on the button and under each row. A kind you have none of is grayed out."] = "Hvor mange Runes of Teleportation og Runes of Portals du bærer på: på knappen og under hver række. En type du ikke har nogen af, er nedtonet.",
	["How many skills you can learn right now and what they cost together. You still train each one yourself."] = "Hvor mange evner du kan lære lige nu, og hvad de koster tilsammen. Du træner stadig hver enkelt selv.",
	["How many tiles side by side."] = "Hvor mange felter side om side.",
	["How many times the notable sound plays."] = "Hvor mange gange den særlige lyd afspilles.",
	["How many times the sound plays."] = "Hvor mange gange lyden afspilles.",
	["How many trades the log keeps; the oldest go first."] = "Hvor mange handler loggen gemmer; de ældste ryger først.",
	["How many uses the item has left, when more than one."] = "Hvor mange ladninger genstanden har tilbage når der er mere end én.",
	["How much ammo to keep when you carry no quiver or ammo pouch. Never buys past this amount."] = "Hvor meget ammunition du vil beholde når du ikke bærer kogger eller ammunitionspung. Køber aldrig mere end denne mængde.",
	["How much of the 3D model the camera shows."] = "Hvor meget af 3D-modellen kameraet viser.",
	["How much of the circle the entries use. 360 is a full ring; less makes an arc."] = "Hvor meget af cirklen punkterne bruger. 360 er en hel ring; mindre giver en bue.",
	["How much of the world shows through the large map."] = "Hvor meget af spilverdenen du kan se gennem det store minikort.",
	["How party and raid members are named. A member without a role or class shown falls back to Party or Raid and a number. \"Only your own aliases\" renames only the characters on your alias list."] = "Hvordan gruppe- og raidmedlemmer navngives. Et medlem hvis rolle eller klasse ikke vises, får i stedet Gruppe eller Raid og et nummer. \"Kun dine egne aliasser\" omdøber kun karaktererne på din aliasliste.",
	["How plates other than your target step back while you have one: lower opacity, or a dark overlay that keeps names readable."] = "Hvordan andre nameplates end dit mål træder i baggrunden når du har et mål: lavere opacitet, eller en mørk overlejring der holder navnene læsbare.",
	["How prices are written. \"Use general setting\" follows Fonts and text > Money."] = "Hvordan priser skrives. \"Brug generel indstilling\" følger Skrifttyper og tekst > Penge.",
	["How see-through the pins are."] = "Hvor gennemsigtige nålene er.",
	["How see-through the transport pins are."] = "Hvor gennemsigtige transportnålene er.",
	["How solid the bar looks."] = "Hvor dækkende bjælken er.",
	["How strong the portrait shows over the health bar."] = "Hvor kraftigt portrættet vises over livsbjælken.",
