	["Learns the next rank of your plan. One click, one rank; nothing else is spent."] = "Lærer den næste rang i din plan. Ét klik, én rang; intet andet bliver brugt.",
	["Learns this one rank now. Nothing else is spent."] = "Lærer kun denne ene rang nu. Intet andet bliver brugt.",
