	["Notes and marks in the right-click menu only, nothing on tooltips; Avoid warnings stay on."] = "Noter og markeringer kun i højreklikmenuen, intet i tooltips; Undgå-advarsler er slået til.",
	["Notes on the world map; the minimap stays clean."] = "Noter på verdenskortet; minikortet er ryddeligt.",
	["Notes only"] = "Kun noter",
