	["NPCs with a mana bar. Skipped when the game hides the power type."] = "NPC'er med en manabjælke. Springes over når spillet skjuler ressourcetypen.",
	["Number of crafts to include in this shopping list. The game's crafting amount stays unchanged."] = "Antal crafts på indkøbslisten. Spillets antal crafts ændres ikke.",
	["Number of healer columns. More columns are used if the list would exceed the screen height."] = "Antal healerkolonner. Der bruges flere kolonner hvis listen ellers ville gå ud over skærmens højde.",
	["Number of private aura slots."] = "Antal pladser til private auraer.",
	["Numbers and Adventurer everywhere, and every player name over characters hidden through the game's settings (put back when Streamer Mode goes off)."] = "Numre og Eventyrer overalt, og alle spillernavne over karakterer skjules via spillets indstillinger (sættes tilbage når Streamertilstand slås fra).",
	["Numbers fly sideways"] = "Tal flyver til siden",
	["Numbers in front of each line of the check view, so a warning points at its line."] = "Numre foran hver linje i tjekvisningen, så en advarsel peger på sin linje.",
	["Numbers only"] = "Kun tal",
	["Numbers over enemies for the damage your pet's spells do."] = "Tal over fjender for skaden fra dit pets evner.",
	["Object ID"] = "Objekt-ID",
	["Objective widgets under the minimap."] = "Widgets med mål under minikortet.",
	["Observed"] = "Registreret",
	["Of the tank's threat"] = "Af tankens aggro",
	["Of those, show only the debuffs the game itself marks for nameplates."] = "Vis kun de af disse debuffs som spillet selv markerer til nameplates.",
	["Off by default. A \"Buy back (3)\" button under the vendor buys back everything you sold this visit, out of combat."] = "Slået fra som standard. En \"Køb tilbage (3)\"-knap under købmanden køber alt tilbage som du har solgt ved dette besøg, uden for kamp.",
	["Off by default. Clicking a reminder casts the missing buff (on you or the first member without it) or uses the consumable: one cast per click, never by itself."] = "Slået fra som standard. Et klik på en påmindelse caster den manglende buff (på dig eller det første medlem uden den) eller bruger forbrugsvaren: én handling pr. klik, aldrig af sig selv.",
	["Off hand"] = "Off hand",
	["Off keeps Blizzard's own %s, untouched. The same switch as on the Blizzard UI page."] = "Når den er slået fra, røres Blizzards egen version af %s ikke. Samme kontakt som på Blizzard-UI-siden.",
	["Off keeps only the key: the button stays invisible and takes no clicks."] = "Når den er slået fra, virker kun tasten: knappen er usynlig og tager ikke imod klik.",
	["Off keeps the game's value (now %s)."] = "Når den er slået fra, bruges spillets værdi (nu %s).",
	["Off leaves these plates exactly as Blizzard draws them. Friendly plates inside instances always stay Blizzard's."] = "Når den er slået fra, ser disse nameplates ud præcis som Blizzard tegner dem. Venlige nameplates i instanser er altid Blizzards.",
	["Off lists only the stats this scale values. On lists all of them so you can add more."] = "Når den er slået fra, vises kun de stats som denne skala vægter. Når den er slået til, vises alle, så du kan tilføje flere.",
	["Off shows them in the main chat as well. Reply, the whisper sound and the taskbar flash work either way. Needs the Blizzard UI switch Improve for chat."] = "Når den er slået fra, vises de også i hovedchatten. Svar, hviskelyden og blink på proceslinjen virker under alle omstændigheder. Kræver Blizzard-UI-kontakten Forbedr for chat.",
	["Off the tooltip"] = "Ikke i tooltip",
	["Off-hand"] = "Off hand",
	["Off-hand imbue"] = "Off Hand-imbue",
	["Off-hand imbue spell"] = "Imbue-evne til Off Hand",
	["Off-hand poison"] = "Gift på off hand",
	["Off-hand weapon"] = "Off Hand-våben",
	["Off: real names show."] = "Fra: rigtige navne vises.",
	["Off: the threat colors of the Colors page, shared with the unit frames. On: the three colors below on nameplates only."] = "Fra: aggrofarverne fra siden Farver, delt med unitframes. Til: de tre farver nedenfor, kun på nameplates.",
	["Offer a restore after a reset"] = "Tilbyd gendannelse efter en nulstilling",
	["Offer to fill ammo when a vendor opens"] = "Tilbyd at fylde ammunition når en købmand åbner",
	["Offer to restock when a vendor opens"] = "Tilbyd at genopfylde når en købmand åbner",
	["Offers the plan to your group, guild or a player who uses EldoUI. They see it before they save it."] = "Tilbyder planen til din gruppe, din guild eller en spiller der bruger EldoUI. De ser den før de gemmer den.",
	["Officer"] = "Officer",
	["Officer chat in its own window."] = "Officerchat i sit eget vindue.",
	["Offline days"] = "Dage offline",
	["Offline members keep a dimmed class color instead of plain gray."] = "Offline medlemmer beholder en nedtonet klassefarve i stedet for almindelig grå.",
	["Offline rows are drawn fainter."] = "Rækker for offline venner tegnes svagere.",
	["Offline."] = "Offline.",
	["Offline: %s."] = "Offline: %s.",
	["Offset"] = "Forskydning",
	["Okay"] = "OK",
	["Old chest"] = "Gammel kiste",
	["Old road"] = "Old road",
	["On a flight path the interface fades to one calm panel with where you fly, the time left and buttons for the map and bags. Landing or combat brings it back. Off by default."] = "På en flyverute toner brugerfladen over i ét roligt panel med hvor du flyver hen, resterende tid og knapper til kortet og taskerne. Landing eller kamp bringer den tilbage. Slået fra som standard.",
	["On a hostile mob's tooltip: the abilities you saw it cast. Shift lists them all."] = "I en fjendtlig mobs tooltip: de evner du har set den caste. Shift viser dem alle.",
	["On a minimap corner (see Group finder eye above) or on its own mover. Needs \"Queue status eye\" with Move in Blizzard UI."] = "I et hjørne af minikortet (se Gruppesøgerens øje ovenfor) eller på sit eget flyttefelt. Kræver \"Køstatus-øje\" med Flyt i Blizzard-UI.",
	["On a mob's tooltip, Tremor, Poison Cleansing or Disease Cleansing Totem when the Mob Abilities log saw it cast fear, poison or disease. The loadout menu offers the swap. Out of combat."] = "I en mobs tooltip: Tremor, Poison Cleansing eller Disease Cleansing Totem når Mobevner-loggen så den caste fear, gift eller sygdom. Loadout-menuen tilbyder skiftet. Uden for kamp.",
	["On a rank you don't use (in the Training window, at a trainer or in a link), also show the values of the rank you know."] = "På en evnerang du ikke bruger (i træningsvinduet, hos en træner eller i et link), vis også værdierne for den evnerang du kender.",
	["On a rare creature: its rank, whether you saw it this session and the mounts, pets, toys or set pieces it drops that you don't own yet."] = "På en rare vises dens rang og om du har set den i denne session. Viser også de mounts, pets, toys eller setdele den dropper som du ikke ejer endnu.",
	["On a spell: damage or healing per second and per mana, and the mana cost as a share of your pool (Spell Efficiency module)."] = "På en evne: skade eller healing pr. sekund og pr. mana og manaprisen som andel af din manapulje (modulet Evneeffektivitet).",
	["On bag, merchant and loot-roll icons. On Blizzard's own bag, merchant and roll windows this also needs that element's Improve switch (Blizzard UI page)."] = "På ikoner i tasker, hos købmanden og ved lootrul. På Blizzards egne vinduer for tasker, købmand og lootrul kræver det også elementets kontakt Forbedr (Blizzard-UI-siden).",
	["On buff and debuff tooltips: the player or pet who cast it. Not shown when the game keeps the caster hidden."] = "På buff- og debuff-tooltips: spilleren eller pettet der kastede den. Vises ikke når spillet holder kasteren skjult.",
	["On flight paths"] = "På flyveruter",
	["On item tooltips"] = "I tooltips for genstande",
	["On items a reputation quest asks for (Valor Tokens, Scourgestones, Insignia): who takes them and how much reputation they give. Needs the Loot Guide's data."] = "På genstande som en omdømmequest beder om (Valor Tokens, Scourgestones, Insignia): hvem der tager imod dem, og hvor meget omdømme de giver. Kræver Loot Guide-data.",
	["On items a reputation quest asks for: where to turn them in and how much reputation they give."] = "På genstande som en omdømmequest beder om: hvor du afleverer dem, og hvor meget omdømme de giver.",
	["On level-up"] = "Ved level-up",
	["On level-up, one card lists what the level brings: your talent point, new spell ranks, class quests, gear and dungeons, each a link. Nothing is spent unless you click."] = "Ved level-up viser et kort hvad levelet bringer: dit talentpoint, nye rangtrin af dine evner, klassequests, udstyr og dungeons, hver som et link. Intet bliver brugt uden at du klikker.",
	["On mouseover"] = "Når musen er over",
	["On my way"] = "På vej",
	["On the \"Raid Warnings\" mover."] = "På flyttefeltet \"Raidadvarsler\".",
	["On the \"Red Error Text\" mover."] = "På flyttefeltet \"Rød fejltekst\".",
	["On the \"Zone Text\" mover."] = "På flyttefeltet \"Zonetekst\".",
	["On the bottom edge"] = "På nederste kant",
	["On the minimap"] = "På minikortet",
	["On the portrait's top or bottom edge, on the frame's corner away from the portrait, or in the circle of the classic frame art (Original game art), which also shows the rest, combat and corpse marks."] = "På portrættets øverste eller nederste kant, i det hjørne af rammen der vender væk fra portrættet, eller i cirklen i den klassiske rammegrafik (Spillets originale grafik). Cirklen viser også hvile-, kamp- og ligmærker.",
	["On the portrait's top or bottom edge, or on the frame's corner away from the portrait."] = "På portrættets øverste eller nederste kant, eller i det hjørne af rammen der vender væk fra portrættet.",
	["On the profession window"] = "På fagvinduet",
	["On the side rail"] = "På sideskinnen",
	["On the totem tooltips"] = "I totemtooltips",
	["On the world map"] = "På verdenskortet",
	["On trainers, weapon masters, vendors and flight masters: what they have for this character right now. Vendors need the Loot Guide data."] = "På trænere, våbenmestre, købmænd og flyvemestre: hvad de har til denne karakter lige nu. Købmænd kræver Loot Guide-dataene.",
	["On your shopping list: %d crafts"] = "På din indkøbsliste: %d crafts",
	["On your shopping list: %d crafts."] = { one = "På din indkøbsliste: %d craft.", other = "På din indkøbsliste: %d crafts." },
	["on | off | toggle  show or hide the quest tracker"] = "on | off | toggle  vis eller skjul questtrackeren",
	["On: EldoUI shows aliases in place of real character names. Also /eui streamer, or a click on the Streamer datatext."] = "Til: EldoUI viser aliasser i stedet for rigtige karakternavne. Også /eui streamer eller et klik på Streamer-datateksten.",
	["On: EldoUI shows aliases in place of real names."] = "Til: EldoUI viser aliasser i stedet for rigtige navne.",
	["On: plates show all the time. Off: only in combat or while the plate key is held."] = "Til: nameplates vises hele tiden. Fra: kun i kamp eller mens nameplatetasten holdes nede.",
	["On: the next vendor opens with the filters you used last. Off: every vendor opens with the filters below. A category or slot the vendor doesn't sell is ignored there."] = "Til: den næste købmand åbner med de filtre du brugte sidst. Fra: hver købmand åbner med filtrene nedenfor. En kategori eller plads som købmanden ikke sælger, ignoreres der.",
	["One"] = "Én",
	["One addon message to your group, out of combat. Nothing is sent on its own."] = "Én addonbesked til din gruppe uden for kamp. Intet sendes af sig selv.",
	["One button lists the teleports and portals you know; click a row to cast it. The list hides in combat."] = "Én knap viser de teleports og portaler du kender; klik på en række for at caste den. Listen skjules i kamp.",
	["One chat line with the gold an open run collected, and how many letters were returned."] = "Én linje i chatten med det guld som Åbn alle har samlet ind, og hvor mange breve der blev returneret.",
	["One chat line: \"Sold 8 junk items and earned 1g 20s\", repairs and restocks."] = "Én chatlinje: \"8 skraldgenstande er solgt for 1g 20s\", reparationer og genopfyldninger.",
	["One color"] = "Én farve",
	["One column of rows beside the window, coin icons."] = "Én kolonne af rækker ved siden af vinduet, møntikoner.",
	["One extra sound on top of the game's own when a whisper arrives, set in Chat (Alerts and filters). It plays for the messenger too."] = "Én ekstra lyd oven i spillets egen når en hvisken ankommer, indstillet i Chat (Advarsler og filtre). Den afspilles også for messengeren.",
	["One line"] = "Én linje",
	["One line a quest with how many of you are on it; the tooltip has the details."] = "Én linje pr. quest med hvor mange af jer der er i gang med den; tooltippen har detaljerne.",
	["One line in the title bar with how many mounts, pets, toys and heirlooms you have."] = "Én linje i titellinjen med hvor mange mounts, pets, toys og heirlooms du har.",
	["One line in your own chat when the leader changes the loot method, the master looter or the threshold. Nothing is sent to the group."] = "Én linje i din egen chat når lederen skifter lootmetode, master looter eller tærskel. Intet sendes til gruppen.",
	["One line per declined request, so nothing disappears silently."] = "Én linje pr. afvist anmodning, så intet forsvinder i stilhed.",
	["One line with the numbers in your accent color (warm sand under the WoW Forever art style)."] = "Én linje med tallene i din accentfarve (en varm sandfarve under grafikstilen WoW Forever).",
	["One line: vendor price (each and stack) plus auction price and its age when an auction module provides them."] = "Én linje: købmandspris (stykpris og stakpris) plus auktionspris og dens alder når et auktionsmodul leverer dem.",
	["One or two columns of rows."] = "En eller to kolonner af rækker.",
	["One per line, like /way Elwynn Forest 45 63 Goldshire. Lines shared from chat work too."] = "Én pr. linje, fx /way Elwynn Forest 45 63 Goldshire. Linjer delt fra chatten virker også.",
	["One portrait style for every unit frame that shows a portrait and for the party frames (Group Frames). Mixed: the frames use different styles; each frame's own style is on its General tab."] = "Én portrætstil til alle unitframes der viser et portræt, og til grupperammerne (Grupperammer). Blandet: rammerne bruger forskellige stilarter; hver rammes egen stil findes på dens fane Generelt.",
	["One quest per talk"] = "Én quest pr. samtale",
	["One row per item with the amount to keep in your bags. Type a name, ID or link, drop an item in, or Alt-click an item at a vendor. Also: /eui restock."] = "Én række pr. genstand med det antal du vil beholde i dine tasker. Skriv et navn, id eller link, slip en genstand, eller Alt-klik på en genstand hos en købmand. Også: /eui restock.",
	["One short line of whole numbers, no inputs and no rank compare."] = "Én kort linje med hele tal, ingen grundtal og ingen sammenligning med din evnerang.",
	["One strip"] = "Én strimmel",
	["One totem per press"] = "Én totem pr. tryk",
	["Only a few quests and events use the talking head, so you may rarely see it."] = "Kun få quests og begivenheder bruger det talende hoved, så du ser det måske sjældent.",
	["Only at max level"] = "Kun ved maks. level",
	["Only Blizzard's nameplate debuffs"] = "Kun Blizzards debuffs til nameplates",
	["Only buffs your group can give"] = "Kun buffs din gruppe kan give",
	["Only changed settings"] = "Kun ændrede indstillinger",
	["Only chosen healers"] = "Kun valgte healere",
	["Only for mages: your character is not a mage, so the button stays hidden."] = "Kun for Mages: din karakter er ikke en Mage, så knappen er skjult.",
	["Only Hunters have pets to train."] = "Kun Hunters har pets at træne.",
	["Only important spells"] = "Kun vigtige evner",
	["Only in a group"] = "Kun i en gruppe",
	["Only in battlegrounds and world PvP, or all the time."] = "Kun i battlegrounds og world PvP eller hele tiden.",
	["Only in the windows"] = "Kun i vinduerne",
	["Only players show a power bar."] = "Kun spillere viser en ressourcebjælke.",
	["Only professions you have"] = "Kun dine fag",
	["Only settings that differ from the game's default or that EldoUI set."] = "Kun indstillinger som afviger fra spillets standard eller som EldoUI har sat.",
	["Only spell icons in the ability row, up to eight."] = "Kun evneikoner i evnerækken, op til otte.",
	["Only the backpack"] = "Kun rygsækken",
	["Only the Cards and Forever bronze looks have bars."] = "Kun udseenderne Kort og Forever bronze har bjælker.",
	["Only the characters on your alias list are renamed."] = "Kun karaktererne på din aliasliste omdøbes.",
