	["Show +Combat / -Combat"] = "Vis +Kamp / -Kamp",
	["Show a card"] = "Vis et kort",
	["Show a consumable reminder (grayed) even when you carry none of it. Off: only when you have one to use."] = "Vis en påmindelse om en forbrugsvare (nedtonet) selv når du ikke har nogen af den. Fra: kun når du har en at bruge.",
	["Show a new quest's title in the tint color in the quest window. Off: only the tag marks it."] = "Vis titlen på en ny quest i farvetonen i questvinduet. Slået fra: kun mærket viser at den er ny.",
