	["Show volume panel"] = "Vis lydstyrkepanel",
	["Show waypoints on the minimap; ones out of range sit on its edge."] = "Vis waypoints på minikortet; dem uden for rækkevidde sidder på kanten.",
	["Show waypoints on the world map. Hover for details, right-click for options."] = "Vis waypoints på verdenskortet. Hold musen over for detaljer, højreklik for indstillinger.",
	["Show when the buff on you is a lower rank than one you know. Out of combat only."] = "Vis når buffen på dig har en lavere rang end en du kender. Kun uden for kamp.",
	["Show whispers only in the messenger"] = "Vis kun hvisken i messengeren",
	["Show whose territory the zone is on the toast."] = "Vis på pop op-beskeden hvis territorium zonen ligger i.",
	["Show your known interrupt's icon and cooldown while your target or focus casts."] = "Vis din kendte afbrydelses ikon og cooldown mens dit mål eller fokus caster.",
	["Show your note and mark on the player's tooltip."] = "Vis din note og markering i spillerens tooltip.",
	["Showcase"] = "Showcase",
	["Showing every family"] = "Viser alle familier",
	["Showing now: Blizzard default plates."] = "Vises nu: Blizzards standardnameplates.",
	["Showing now: Blizzard plates with EldoUI's look."] = "Vises nu: Blizzards nameplates med EldoUI's udseende.",
	["Showing now: Blizzard's plates (the Nameplates module is off)."] = "Vises nu: Blizzards nameplates (Nameplates-modulet er slået fra).",
	["Showing now: EldoUI plates. Blizzard's plate is faded out under them."] = "Vises nu: EldoUI-nameplates. Blizzards nameplate er tonet ud under dem.",
	["Showing what a %s can learn"] = "Viser hvad en %s kan lære",
	["Shown normally"] = "Vist normalt",
	["Shown once you know it: remind me when this buff is missing, running out or a higher rank is known. Off by default."] = "Vises når du kender den: påmind mig når denne buff mangler, er ved at løbe ud eller en højere rang er kendt. Fra som standard.",
	["Shown under (or above) the window while the Blizzard UI switch \"Improve (extra info)\" is on for the trade window."] = "Vises under (eller over) vinduet mens Blizzard-UI-kontakten \"Forbedr (ekstra info)\" er slået til for byttevinduet.",
	["Shown while you rest in an inn or city."] = "Vises mens du hviler på en kro eller i en by.",
	["Shows a number for every auto-attack hit, not only for hits that do something special."] = "Viser et tal for hvert auto-attack-slag, ikke kun for slag der gør noget særligt.",
	["Shows a sample battleground message (/eui notify test bg)."] = "Viser et eksempel på en battleground-besked (/eui notify test bg).",
	["Shows a sample raid warning."] = "Viser et eksempel på en raidadvarsel.",
	["Shows a sample red error."] = "Viser et eksempel på en rød fejl.",
	["Shows a sample tooltip for 5 seconds. It updates as you change settings."] = "Viser en eksempeltooltip i 5 sekunder. Den opdateres mens du ændrer indstillinger.",
	["Shows each spell's icon in front of its name."] = "Viser hver evnes ikon foran navnet.",
	["Shows estimated skill-up thresholds for the selected recipe."] = "Viser anslåede grænser for skillups for den valgte opskrift.",
	["Shows every item with its amount and the total cost before anything is bought. Strongly recommended."] = "Viser hver genstand med antal og samlet pris før noget bliver købt. Anbefales stærkt.",
	["Shows every point of your plan again."] = "Viser igen alle point i din plan.",
	["Shows how many crafts fit your bags, bank, and saved character inventories, with a button to list missing reagents."] = "Viser hvor mange crafts dine tasker, din bank og gemte karakterbeholdninger rækker til, med en knap til at sætte manglende reagenser på listen.",
	["Shows how many times a player from the other faction has killed this character, when the game identified the killer."] = "Viser antallet af gange en spiller fra den modsatte fraktion har dræbt din karakter. Spillet skal kunne fastslå hvem der dræbte dig.",
	["Shows imported soft reserves and That's My BiS lists on item tooltips and loot rolls, and keeps a GDKP ledger. You roll and trade yourself."] = "Viser importerede soft reserves og That's My BiS-lister i tooltips for genstande og ved lootrul og fører et GDKP-regnskab. Du ruller og bytter selv.",
	["Shows listings whose leader or activity name has this text. The game keeps listing comments from addons, so they can't be searched."] = "Viser opslag hvor lederens navn eller aktivitetens navn indeholder denne tekst. Spillet skjuler opslagenes kommentarer for addons, så der kan ikke søges i dem.",
	["Shows on EldoUI's minimap, which the Blizzard UI step turns on (Recommended, Only EldoUI's own frames or Everything)."] = "Vises på EldoUI's minikort. Blizzard-UI-trinnet slår det til (Anbefalet, Kun EldoUI's egne rammer eller Alt).",
	["Shows or hides the panel now (/eui volume)."] = "Viser eller skjuler panelet nu (/eui volume).",
	["Shows payouts in whole gold, rounded down. The rest stays with the organizer."] = "Viser udbetalinger i hele guld, rundet ned. Resten bliver hos arrangøren.",
	["Shows percentages from the first corpse on."] = "Viser procenter allerede fra det første lig.",
	["Shows reagent costs and possible auction or vendor profit from your saved prices. Missing prices stay marked."] = "Viser reagenspriser og mulig fortjeneste ved salg på auktion eller til en købmand ud fra dine gemte priser. Manglende priser markeres.",
	["Shows the bar outside a group so you can place and try it. Also /eui raidtools."] = "Viser bjælken uden for en gruppe så du kan placere og afprøve den. Også /eui raidtools.",
	["Shows the chat command for the distance above, selected for copying. Paste it in chat and press Enter."] = "Viser chatkommandoen for afstanden ovenfor, markeret til kopiering. Indsæt den i chatten og tryk på Enter.",
	["Shows the linked main beside an alt's name in guild chat. Off by default."] = "Viser den tilknyttede main ved siden af en alts navn i guildchatten. Slået fra som standard.",
	["Shows the listings you dismissed again."] = "Viser igen de opslag du har afvist.",
	["Shows the loot method, the master looter and the threshold. The group leader clicks it to change them; for everyone else it only shows what the leader set."] = "Viser lootmetoden, master looteren og tærsklen. Gruppelederen klikker for at skifte dem; for alle andre viser den kun det lederen har valgt.",
	["Shows the numbers on the experience bar without hovering (game setting; off puts your own value back)."] = "Viser tallene på XP-bjælken uden at du holder musen over (spilindstilling; fra sætter din egen værdi tilbage).",
	["Shows the partner's name in their class color."] = "Viser partnerens navn i partnerens klassefarve.",
	["Shows the path in the Talent Planner's Builds tab. Nothing changes until you copy it into a plan there."] = "Viser stien på fanen Builds i talentplanlæggeren. Intet ændres før du kopierer den til en plan der.",
	["Shows the planner window (also /eui talents, a key binding, the Spec block on the Info Bar with Shift-click, and the Menu block)."] = "Viser planlæggervinduet (også /eui talents, en genvejstast, Spec-blokken på Infobjælken med Shift-klik og Menu-blokken).",
	["Shows the prompt for 15 seconds with test text, so you can see it and place it (/eui move: \"Summon and Resurrection Prompt\"). Its buttons only close it."] = "Viser forespørgslen i 15 sekunder med testtekst, så du kan se den og placere den (/eui move: \"Summon- og genoplivningsforespørgsel\"). Dens knapper lukker den kun.",
	["Shows the snapshot's Edit Mode layout as text for Edit Mode > Layouts > Import."] = "Viser øjebliksbilledets Edit Mode-layout som tekst til Edit Mode > Layouts > Import.",
	["Shows the soft-reserve line (SR: names, with +N for a bonus)."] = "Viser soft reserve-linjen (SR: navne, med +N for en bonus).",
	["Shows the That's My BiS line (TMB: names with their prio, or wish for a wishlist entry)."] = "Viser That's My BiS-linjen (TMB: navne med deres prio, eller ønske for en post på ønskelisten).",
	["Shows the window with what you can learn (also /eui training and the Training info bar block)."] = "Viser vinduet med det du kan lære (også /eui training og blokken Træning i Infobjælken).",
	["Shows three sample toasts (/eui notify test lane)."] = "Viser tre eksempler på pop op-beskeder (/eui notify test lane).",
