	["That player could not be added to the bench."] = "Spilleren kunne ikke sættes på bænken.",
	["That snapshot string holds no action bars."] = "Strengen indeholder ingen handlingslinjer.",
	["That snapshot string was changed or damaged (the checksum doesn't match). Copy it again in full."] = "Strengen er ændret eller beskadiget (kontrolsummen passer ikke). Kopier den igen i sin helhed.",
	["That snapshot was taken on another class; its spells were skipped."] = "Øjebliksbilledet blev taget på en anden klasse; dets evner blev sprunget over.",
	["That suggested path isn't available."] = "Den foreslåede sti er ikke tilgængelig.",
	["That talent is already at its full rank in your plan."] = "Det talent er allerede på fuld rang i din plan.",
	["That talent isn't in your class's tree."] = "Det talent findes ikke i din klasses træ.",
	["The \"...\" button that opens the addon button bin."] = "Knappen \"...\" der åbner samlekassen til addonknapper.",
	["The \"skip this cutscene?\" dialogs and the tutorial window in the EldoUI look."] = "Dialogerne \"spring denne cutscene over?\" og vejledningsvinduet i EldoUI-udseendet.",
	["The + and - buttons; Blizzard shows them while you point at the map."] = "Knapperne + og -; Blizzard viser dem mens du peger på kortet.",
	["The 36 px button hides in combat, like its list."] = "Knappen på 36 px skjules i kamp ligesom dens liste.",
	["The abilities each mob cast in front of you."] = "De evner hver mob har castet foran dig.",
	["The ability log is empty again."] = "Evneloggen er tom igen.",
	["The accept helper skips quests the game shows in gray (too low for your level). You can still take them yourself."] = "Accepthjælperen springer quests over som spillet viser i gråt (for lave til dit level). Du kan stadig selv tage dem.",
	["The air totem the air button drops."] = "Den lufttotem som luftknappen sætter.",
	["The alternate power bar some encounters use."] = "Den alternative ressourcebjælke som nogle encounters bruger.",
	["The armor figure that shows when your gear is damaged. Move, scale or hide it with its switches on the Blizzard UI page."] = "Rustningsfiguren der vises når dit udstyr er beskadiget. Flyt, skaler eller skjul den med dens kontakter på siden Blizzard-UI.",
	["The arrow points here."] = "Pilen peger herhen.",
	["The art style's thin frame line around the tracker (bronze under WoW Forever)."] = "Grafikstilens tynde rammelinje rundt om trackeren (bronze under WoW Forever).",
	["The Auction module is not loaded."] = "Auktionsmodulet er ikke indlæst.",
	["The bag buttons side by side."] = "Taskeknapperne side om side.",
	["The bag buttons top to bottom."] = "Taskeknapperne oppefra og ned.",
	["The banner after a boss kill with its loot."] = "Banneret efter et bossdrab med dets loot.",
	["The bar fades from the high to the low health color as the unit loses health. Set both colors on the Colors page."] = "Bjælken glider fra den høje til den lave livsfarve efterhånden som enheden mister liv. Begge farver vælger du på siden Farver.",
	["The bar starts with your role's spells, plus Totemic Recall, Reincarnation and Earth Shock. Your own ticks stay; unknown spells never show."] = "Linjen starter med din rolles evner plus Totemic Recall, Reincarnation og Earth Shock. Dine egne flueben bevares; ukendte evner vises aldrig.",
	["The bars already match"] = "Linjerne passer allerede",
	["The bars stand upright side by side and fill from the bottom. Their text moves into the tooltip."] = "Bjælkerne står lodret side om side og fyldes nedefra. Teksten flytter ind i tooltippen.",
	["The Best of all total adds up the best times; it needs a time for every level before."] = "Totalen for Bedste af alle lægger de bedste tider sammen; den kræver en tid for hvert level før.",
	["The big level-up and new spell toast in the middle of the screen."] = "Den store pop op-besked om nyt level og nye evner midt på skærmen.",
	["The boss you just defeated."] = "Bossen du lige har besejret.",
	["The bound key in the button's top corner."] = "Den tildelte tast i knappens øverste hjørne.",
	["the box is empty"] = "feltet er tomt",
	["The browse / listing / who tabs on the right as flat icon boxes with the accent on the open one."] = "Fanerne til gennemsyn / opslag / spillersøgning til højre som flade ikonbokse med accentfarve på den åbne.",
	["The browser also lists debug and GM settings and the ones the game locks or shows read-only (those stay read-only)."] = "Browseren viser også debug- og GM-indstillinger og dem som spillet låser eller viser som skrivebeskyttede (de er stadig skrivebeskyttede).",
	["The browser lists only settings that differ from the game's default or that EldoUI set."] = "Browseren viser kun indstillinger som afviger fra spillets standard eller som EldoUI har sat.",
	["The buff or item name under each icon."] = "Buffens eller genstandens navn under hvert ikon.",
	["The button glows for a few seconds when a new quest item lands on it (look under the Glows page)."] = "Knappen gløder i nogle sekunder når en ny questgenstand dukker op på den (se under siden Glød).",
	["The camera distance is set after combat."] = "Kameraafstanden sættes efter kampen.",
	["The camera distance where the whole offset applies."] = "Den kameraafstand hvor hele forskydningen gælder.",
	["The camera looks a little down when zoomed out, for a wider view. An experimental game setting: the game may change or drop it."] = "Kameraet kigger lidt nedad når det er zoomet ud, så du ser mere. En eksperimentel spilindstilling: spillet kan ændre eller fjerne den.",
	["The camera stops at the water surface instead of going under it."] = "Kameraet stopper ved vandoverfladen i stedet for at gå under den.",
	["The camera tilts up a little as you zoom out, so you see more ahead of you."] = "Kameraet vipper lidt op når du zoomer ud, så du ser mere foran dig.",
	["The camera tilts with the ground when you walk up or down a hill."] = "Kameraet hælder med terrænet når du går op eller ned ad en bakke.",
	["The card closes a few seconds after the rare dies."] = "Kortet lukker et par sekunder efter at raren dør.",
	["The card opens after combat."] = "Kortet åbnes efter kampen.",
	["The card, no sound"] = "Kortet, ingen lyd",
	["The card, no sound: the card shows; no sound, flash, chat line or vibration. Nothing: no card either, and it is not listed under This session."] = "Kortet, ingen lyd: kortet vises; ingen lyd, blink, chatlinje eller vibration. Intet: heller intet kort, og den står ikke under Denne session.",
	["The cast bar color when its color mode is Own color."] = "Castbarens farve når farvetilstanden er Egen farve.",
	["The cast time on the right of the bar."] = "Casttiden til højre på bjælken.",
	["The channels above no longer show in the main chat (needs the Blizzard UI switch Improve for chat windows)."] = "Kanalerne ovenfor vises ikke længere i hovedchatten (kræver Blizzard-UI-kontakten Forbedr for chatvinduer).",
	["The character to race. Without one, Personal best is used."] = "Den karakter du kappes med. Vælger du ingen, bruges Personlig rekord.",
	["The character whose splits you look at."] = "Den karakter hvis mellemtider du ser på.",
	["The characters whose reagents and recipe cooldowns count. On Forever, this realm means everyone on the same ruleset."] = "De karakterer hvis reagenser og opskriftscooldowns tæller med. På Forever betyder denne realm alle med samme regelsæt.",
	["The cheapest recipes to level a profession, from your saved prices."] = "De billigste opskrifter til at levele et fag, ud fra dine gemte priser.",
	["The chip needs Improve switched on for the minimap in Blizzard UI."] = "Chippen kræver at Forbedr er slået til for minikortet i Blizzard UI.",
	["The class icon in place of the game icon while a friend plays a WoW character."] = "Klasseikonet i stedet for spillets ikon mens en ven spiller en WoW-karakter.",
	["The classic resting icon or a small zzz."] = "Det klassiske hvileikon eller et lille zzz.",
	["The click drawer stays open or closed the way you left it, also after a reload."] = "Klikskuffen er åben eller lukket som du forlod den, også efter en genindlæsning.",
	["The clock time you land, after the time left."] = "Klokkeslættet du lander, efter den resterende tid.",
	["The color of new quests and the tag."] = "Farven på nye quests og mærket.",
	["The color of the empty part of the health bar when its mode is Own color."] = "Farven på livsbjælkens tomme del når dens tilstand er Egen farve.",
	["The Copy button adds how long ago each trade was (\"3h ago\")."] = "Knappen Kopier tilføjer hvor længe siden hver handel var (\"3t siden\").",
	["The Copy button adds the zone or instance to each line."] = "Knappen Kopier tilføjer zonen eller instansen til hver linje.",
	["The Copy button in the log adds the date and time to each line."] = "Knappen Kopier i loggen tilføjer dato og klokkeslæt til hver linje.",
	["The cursor"] = "Markøren",
	["The cut and its gold, such as: Tank repairs 300"] = "Andelen og dens guld, fx: Tankreparationer 300",
	["The debuffs picked by the Auras tab filter, above the plate."] = "Debuffs valgt af filteret på fanen Auraer, vist over nameplaten.",
	["The dialogs' EldoUI panels let the game show through a little. How much: General > Panel opacity."] = "Dialogernes EldoUI-paneler lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The earth totem button while you are feared and know Tremor Totem (Shaman Totems > Group)."] = "Jordtotemknappen mens du er feared og kender Tremor Totem (Shaman-totems > Gruppe).",
	["The earth totem the earth button drops. Right-click a totem in the button's picker does the same."] = "Den jordtotem som jordknappen sætter. Højreklik på en totem i knappens vælger gør det samme.",
	["The edge of the map that holds the slim button rail. Buttons set to \"On the side rail\" sit on it one under the other, each with a tooltip naming it."] = "Den kant af kortet der har den smalle knapskinne. Knapper der er sat til \"På sideskinnen\", sidder på den under hinanden, hver med en tooltip der viser navnet.",
	["The editor lets the game show through a little. How much: General > Panel opacity."] = "Editoren lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The EldoUI editor opens and closes together with Blizzard's macro window, and follows its selection. Off: open it with the Edit in EldoUI button."] = "EldoUI-editoren åbner og lukker sammen med Blizzards makrovindue og følger dets valg. Fra: åbn den med knappen Rediger i EldoUI.",
	["The EldoUI look with see-through panels."] = "EldoUI-udseendet med gennemsigtige paneler.",
	["The EldoUI look with smaller group finder list text and Player Notes marks on listings."] = "EldoUI-udseendet med mindre tekst i gruppesøgerens liste og mærker fra Spillernoter på opslag.",
	["The EldoUI look, following the mouse."] = "EldoUI-udseendet, og tooltippen følger musen.",
	["The EldoUI version of members who share it; an older one than yours shows orange."] = "EldoUI-versionen for medlemmer der deler den; en ældre end din vises i orange.",
	["The elixirs, flasks, food and weapon enchants you picked on the Consumables tab."] = "De eliksirer, flasks, madvarer og våbenenchants du valgte på fanen Forbrugsvarer.",
	["The enemy's buffs picked on the Auras tab."] = "Fjendens buffs valgt på fanen Auraer.",
	["The Enter Battle popup's skin and countdown bar are set under Messages > Ready check."] = "Skin og nedtællingsbjælke til pop op-vinduet Enter Battle indstilles under Beskeder > Klar-tjek.",
	["The expansion landing page button, if the game shows one."] = "Knappen til udvidelsens startside hvis spillet viser en.",
	["The extra icons from the Indicators tab on this type."] = "Ekstra ikoner fra fanen Indikatorer på denne type.",
	["The faction you watch (tick \"Show as experience bar\" in the reputation list)."] = "Den fraktion du følger (sæt flueben i omdømmelisten for at vise den som erfaringsbjælke).",
	["The filters you chose are still on next time you log in. Off: they start cleared every session."] = "De filtre du har valgt, er stadig slået til næste gang du logger ind. Fra: de starter tomme i hver session.",
	["The fire totem the fire button drops."] = "Den ildtotem som ildknappen sætter.",
	["The first complete roster is the starting point for history."] = "Historikken starter med den første komplette medlemsliste.",
	["The first line: item or unit name."] = "Første linje: navnet på genstanden, spilleren eller NPC'en.",
	["The fishing skill from which no fish get away in the zone."] = "Den Fishing-skill hvor ingen fisk slipper væk i zonen.",
	["The flat tracking button shows the icon of the tracking you have on, such as Find Herbs, and is dimmed while nothing is tracked. It still opens the game's tracking menu."] = "Den flade registreringsknap viser ikonet for den registrering du har slået til, fx Find Herbs, og er nedtonet mens intet registreres. Den åbner stadig spillets registreringsmenu.",
	["The flight timer bar is part of Quality of Life."] = "Flyvenedtællingens bjælke hører under Livskvalitet.",
	["The flight view's panel with a sample flight, in your art style and accent."] = "Flyvevisningens panel med en eksempelflyvning i din grafikstil og accentfarve.",
	["The frame"] = "Rammen",
	["The frame art of every EldoUI unit frame: portrait ring or frame, bar border and fill. It never changes positions, sizes, bars or what the portrait shows. Blizzard's own frames are not affected."] = "Rammegrafikken på alle EldoUI's unitframes: portrætring eller -ramme, bjælkekant og fyld. Den ændrer aldrig placeringer, størrelser, bjælker eller hvad portrættet viser. Blizzards egne rammer påvirkes ikke.",
	["The frame the tabs edit, with sample values, in its current size, colors and texts."] = "Rammen som fanerne redigerer, med eksempelværdier, i dens nuværende størrelse, farver og tekster.",
	["The frame this tab changes. Every tab edits the same unit, so pick it once and walk through the tabs."] = "Rammen som denne fane ændrer. Alle faner redigerer den samme enhed, så vælg den én gang, og gå fanerne igennem.",
	["The friends, guild, calendar, group finder and PvP windows let the game show through a little. How much: General > Panel opacity."] = "Vinduerne for venner, guild, kalender, gruppesøger og PvP lader spillet skinne en smule igennem. Hvor meget: Generelt > Panelopacitet.",
	["The game called off the layer move."] = "Spillet aflyste layer-flytningen.",
	["The game declines invites to chat channels for you, without asking."] = "Spillet afviser invitationer til chatkanaler for dig uden at spørge.",
	["The game did not add %s."] = "Spillet tilføjede ikke %s.",
	["The game did not allow this right now."] = "Spillet tillod ikke dette lige nu.",
	["The game did not ignore %s."] = "Spillet ignorerede ikke %s.",
	["The game did not invite %s."] = "Spillet inviterede ikke %s.",
	["The game did not save the macro."] = "Spillet gemte ikke makroen.",
	["The game did not take that value."] = "Spillet tog ikke imod den værdi.",
	["The game did not take the sound."] = "Spillet tog ikke imod lyden.",
	["The game didn't accept the change. Nothing was learned."] = "Spillet godtog ikke ændringen. Intet blev lært.",
	["The game does not let addons read this member's buffs right now."] = "Spillet lader ikke addons læse dette medlems buffs lige nu.",
	["The game doesn't give your position here."] = "Spillet giver ikke din placering her.",
	["The game doesn't let you change talents right now."] = "Spillet lader dig ikke ændre talenter lige nu.",
	["The game doesn't list this class's talent tree right now. Try again in a moment."] = "Spillet viser ikke klassens talenttræ lige nu. Prøv igen om lidt.",
	["The game doesn't show the %s tree here, so the plan is checked when a %s opens it."] = "Spillet viser ikke %s-træet her, så planen tjekkes når en %s åbner den.",
	["The game doesn't show the %s tree to this character, so the link can't be read here. Paste it on a %s."] = "Spillet viser ikke %s-træet for denne karakter, så linket kan ikke læses her. Indsæt det på en %s.",
	["The game doesn't show the %s tree to this character. Your %s plans are kept and open on a %s."] = "Spillet viser ikke %s-træet for denne karakter. Dine %s-planer bevares og kan åbnes på en %s.",
	["The game flashes in the taskbar when a pop-up appears."] = "Spillet blinker på proceslinjen når et pop op-vindue dukker op.",
	["The game has no help text for this setting."] = "Spillet har ingen hjælpetekst til denne indstilling.",
	["The game hasn't sent your talent tree yet. Open the planner again in a moment."] = "Spillet har ikke sendt dit talenttræ endnu. Åbn planlæggeren igen om lidt.",
	["The game hides which totem is down right now; the timer shows again when it tells."] = "Spillet skjuler hvilken totem der står lige nu; nedtællingen vises igen når spillet oplyser det.",
	["The game limits how often you can change layer. Try again in a few minutes."] = "Spillet begrænser hvor tit du kan skifte layer. Prøv igen om et par minutter.",
	["The game locks this setting."] = "Spillet låser denne indstilling.",
	["The game marks the unit for one of your quests. Outside instances only."] = "Spillet markerer enheden til en af dine quests. Kun uden for instanser.",
	["The game may have reset your setup: %s."] = "Spillet har måske nulstillet din opsætning: %s.",
	["The game menu buttons are in the Menu block on the Info Bar now. To get the micro menu back, turn off \"Replace with EldoUI's frame\" for it on the Blizzard UI page in /eui."] = "Spillets menuknapper er nu i blokken Menu på infobjælken. Slå \"Erstat med EldoUI's ramme\" fra for mikromenuen på siden Blizzard-UI i /eui for at få den tilbage.",
	["The game moves you in %s."] = "Spillet flytter dig om %s.",
	["The game moves you to the group's layer."] = "Spillet flytter dig til gruppens layer.",
	["The game names no zone here."] = "Spillet angiver ingen zone her.",
	["The game plays this sound the moment your shield leaves you, in combat too. Off by default."] = "Spillet afspiller denne lyd i det øjeblik dit skjold forsvinder, også i kamp. Slået fra som standard.",
	["The game refused %s. Nothing was learned."] = "Spillet afviste %s. Intet blev lært.",
	["The game replaces rude words in chat with symbols."] = "Spillet erstatter grove ord i chatten med symboler.",
	["The game shows this setting but does not let it change."] = "Spillet viser denne indstilling, men lader dig ikke ændre den.",
	["The game uses it on its own; the number is how many you carry."] = "Spillet bruger den af sig selv; tallet er hvor mange du bærer på.",
	["The game version EldoUI checked the path on."] = "Den spilversion som EldoUI tjekkede stien på.",
	["The game's classification (the dragon on the target frame)."] = "Spillets klassificering (dragen på målrammen).",
	["The game's countdown numbers on each running totem."] = "Spillets nedtællingstal på hver aktiv totem.",
	["The game's default value."] = "Spillets standardværdi.",
	["The game's flight master art and a shape per kind."] = "Spillets flyvemestergrafik og en form pr. type.",
	["The game's happy, content or unhappy face in the corner of every stabled pet."] = "Spillets glade, tilfredse eller utilfredse ansigt i hjørnet af hvert pet i stalden.",
	["The game's link button during special events. It shows only while an event runs."] = "Spillets linkknap under særlige begivenheder. Den vises kun mens en begivenhed kører.",
	["The game's map pin"] = "Spillets kortnål",
	["The game's name for the setting. A dot marks a value that differs from the game's default."] = "Spillets navn for indstillingen. En prik markerer en værdi der afviger fra spillets standard.",
	["The game's own micro menu, placed by Blizzard's Edit Mode. EldoUI stops moving it, and this box leaves move mode; \"Let EldoUI place the micro menu\" on its options page brings EldoUI's layout back."] = "Spillets egen mikromenu, placeret af Blizzards Edit Mode. EldoUI holder op med at flytte den, og dette flyttefelt forsvinder fra flyttetilstand; \"Lad EldoUI placere mikromenuen\" på dens indstillingsside henter EldoUI's layout tilbage.",
	["The game's own rare and treasure map icons, whatever the art style."] = "Spillets egne kortikoner for rares og skatte, uanset grafikstil.",
	["The game's own short help text, where it has one."] = "Spillets egen korte hjælpetekst hvis den findes.",
	["The game's quality preset: 1 is fastest, 10 looks best. The detailed graphics settings follow the step, as in the game's own menu."] = "Spillets kvalitetspreset: 1 er hurtigst, 10 ser bedst ud. Spillets detaljerede grafikindstillinger følger trinnet som i spillets egen menu.",
	["The game's tutorial pop-ups (game setting showTutorials)."] = "Spillets pop op-vinduer med vejledning (spilindstillingen showTutorials).",
	["The gem socketing window."] = "Vinduet hvor du sætter gems i.",
	["The glow a nameplate style filter rule puts on matching plates."] = "Den glød som en stilfilterregel for nameplates lægger på de nameplates der matcher.",
	["The green mark means this item beats what you wear, rated by the stat weights of your scale. The Upgrades page picks the scale and how big a gain counts."] = "Det grønne mærke betyder at denne genstand er bedre end det du har på, vurderet ud fra statvægtene i din skala. Siden Opgraderinger vælger skalaen og hvor stor en forbedring der tæller.",
	["The grid in a solid panel that follows your art style (the bronze frame line under WoW Forever), 22 px rows."] = "Gitteret i et uigennemsigtigt panel som følger din grafikstil (bronzerammelinjen under WoW Forever), rækker på 22 px.",
	["The group journal on tooltips, no menu entries."] = "Gruppejournalen i tooltips, ingen menupunkter.",
	["The group plan can be sent out of combat."] = "Gruppeplanen kan sendes uden for kamp.",
	["the header has no column for %s"] = "overskriften har ingen kolonne til %s",
	["The health bar color when the color mode is One color."] = "Livsbjælkens farve når farvetilstanden er Én farve.",
	["The health bar color while this filter matches."] = "Livsbjælkens farve mens dette filter matcher.",
	["The health percent \"In execute range\" starts at."] = "Den livsprocent hvor \"I execute-område\" starter.",
	["The height of each row in the history."] = "Højden på hver række i historikken.",
	["The Herbalism, Mining or Skinning rank a node or corpse needs, colored by your own rank like the profession window (red: too low, gray: no more skill-ups)."] = "Den skill i Herbalism, Mining eller Skinning som en node eller et lig kræver, farvet efter din egen skill som i fagvinduet (rød: for lav, grå: ingen flere skillups).",
	["The hop request could not be sent."] = "Hop-forespørgslen kunne ikke sendes.",
	["The imbue the main-hand icon casts."] = "Den imbue som Main Hand-ikonet caster.",
	["The imbue the off-hand icon casts (it then goes on the off-hand weapon)."] = "Den imbue som Off Hand-ikonet caster (den kommer så på dit Off Hand-våben).",
	["The imbue this hand's reminder asks for and a click casts. Automatic: the one you cast last. Any imbue on the hand meets it."] = "Den imbue denne hånds påmindelse beder om, og som et klik caster. Automatisk: den du castede sidst. Enhver imbue på hånden tæller.",
	["The important cast glow, the interrupter's name and the important cast sound are on the Effects tab."] = "Gløden for vigtige casts, navnet på den der afbryder, og lyden for vigtige casts findes på fanen Effekter.",
	["The inspected player's average item level, under the level line."] = "Den inspicerede spillers gennemsnitlige item level, under levellinjen.",
	["the instance types checked under Instances"] = "de instanstyper der er afkrydset under Instanser",
	["The item ID shows on Shift through the Tooltip page (Items and spells > Item ID)."] = "Genstands-ID'et vises med Shift via siden Tooltip (Genstande og evner > Genstands-ID).",
	["The item level of each item the inspected player wears."] = "Item level for hver genstand den inspicerede spiller har på.",
	["The job in a group this path is made for."] = "Den rolle i gruppen som stien er lavet til.",
	["The key text turns red while the game says your target is out of the item's range."] = "Tasteteksten bliver rød mens spillet siger at dit mål er uden for genstandens rækkevidde.",
	["The kind of place you are in."] = "Den slags sted du er på.",
	["The last 50 players from your group journal."] = "De seneste 50 spillere fra din gruppejournal.",
	["The layer you are on as a short code on the map, read from the creatures around you. Click it to hop to another layer. Hidden in instances."] = "Dit layer vises som en kort kode på kortet, aflæst fra væsnerne omkring dig. Klik for at hoppe til et andet layer. Skjult i instanser.",
	["The ledger as text: sales, pot, cuts and payouts."] = "Regnskabet som tekst: salg, pot, andele og udbetalinger.",
	["The level in the game's difficulty color, with elite or rare added."] = "Levelet i spillets sværhedsfarve, med elite eller rare tilføjet.",
	["The level range of the zone under the cursor (or of the map shown), from the game's map data."] = "Levelintervallet for zonen under markøren (eller for det viste kort) fra spillets kortdata.",
	["The level that took the least played time."] = "Det level der tog mindst spilletid.",
	["The level that took the most played time."] = "Det level der tog mest spilletid.",
	["The level this point is for: one point per level from 10."] = "Det level pointet hører til: ét point pr. level fra level 10.",
	["The level time in your accent color (warm sand under the WoW Forever art style)."] = "Leveltiden i din accentfarve (en varm sandfarve under grafikstilen WoW Forever).",
	["The level-up toast lists the spells and ranks your class trainer teaches from your new level that you don't know yet. Needs the Training module."] = "Pop op-beskeden ved nyt level viser de evner og rangtrin din klassetræner lærer dig fra dit nye level og som du endnu ikke kender. Kræver modulet Træning.",
	["The leveling plan uses only recipes you already know. Off: it also lists recipes you can still learn, marked Learn."] = "Levelplanen bruger kun opskrifter du allerede kender. Fra: den viser også opskrifter du stadig kan lære, markeret Lær.",
	["The line comes when the profession is five points from the cap too, so you can plan the trip to the trainer."] = "Linjen kommer også når faget er fem point fra loftet, så du kan planlægge turen til træneren.",
	["The link asks for %d ranks of %s, more than it has. It was made for other trees."] = { one = "Linket beder om %d rangtrin i %s, mere end talentet har. Det er lavet til andre træer.", other = "Linket beder om %d rangtrin i %s, flere end talentet har. Det er lavet til andre træer." },
	["The link has %d points, more than a plan holds. The rest are left out."] = { one = "Linket har %d point, mere end en plan kan rumme. Resten udelades.", other = "Linket har %d point, flere end en plan kan rumme. Resten udelades." },
	["The link has %d talent trees, more than WoW: Forever's %s has."] = { one = "Linket har %d talenttræ, flere end WoW: Forevers %s har.", other = "Linket har %d talenttræer, flere end WoW: Forevers %s har." },
	["The link has no talent points in it."] = "Linket indeholder ingen talentpoint.",
	["The link keeps only the final ranks: the plan takes lower rows first. Reorder it in the planner."] = "Linket indeholder kun hvert talents endelige rang: planen tager de lavere rækker først. Ændr rækkefølgen i planlæggeren.",
	["The link lists %d talents in %s, more than WoW: Forever's tree has. It was made for other trees."] = { one = "Linket angiver %d talent i %s, flere end WoW: Forevers træ har. Det er lavet til andre træer.", other = "Linket angiver %d talenter i %s, flere end WoW: Forevers træ har. Det er lavet til andre træer." },
	["The link names a talent %s doesn't have. It was made for other trees."] = "Linket nævner et talent som %s ikke har. Det er lavet til andre træer.",
	["The link's buying order isn't read: the plan takes lower rows first. Reorder it in the planner."] = "Linkets købsrækkefølge læses ikke: planen tager de lavere rækker først. Ændr rækkefølgen i planlæggeren.",
	["The liquid in the orbs swirls slowly. Off keeps it still. It is also still while Animations is off on the General page."] = "Væsken i kuglerne hvirvler langsomt. Slået fra står den stille. Den står også stille, så længe Animationer er slået fra på siden Generelt.",
	["The list closes once you click a spell in it."] = "Listen lukker når du klikker på en evne i den.",
	["The list is full (%d aliases)."] = "Listen er fuld (%d aliasser).",
	["The loadout %s switches when combat ends."] = "Der skiftes til loadoutet %s når kampen er slut.",
	["The loadout in battlegrounds and arenas."] = "Loadoutet i battlegrounds og arenaer.",
	["The loadout in dungeons."] = "Loadoutet i dungeons.",
	["The loadout in raids."] = "Loadoutet i raids.",
	["The loadout outside instances."] = "Loadoutet uden for instanser.",
	["The look only: no extra lines, counts or buttons."] = "Kun udseendet: ingen ekstra linjer, tællere eller knapper.",
	["The Loot Guide's dungeon and raid entrance pins on the world map."] = "Nålene fra Loot Guide for dungeon- og raidindgange på verdenskortet.",
	["The lowest item durability of you and of members who share it."] = "Den laveste holdbarhed på dit udstyr og på udstyret hos medlemmer der deler den.",
	["The macro %s already exists. Find it under Macros (/macro), Character tab."] = "Makroen %s findes allerede. Find den under Makroer (/macro), fanen Karakter.",
	["The macro names a lower rank of a spell you know at a higher rank. Changes only the rank number to the highest rank you know (out of combat). Undo puts the old text back."] = "Makroen nævner en lavere rang af en evne du kender i en højere rang. Ændrer kun rangnummeret til den højeste rang du kender (uden for kamp). Fortryd sætter den gamle tekst tilbage.",
	["The macro needs a name."] = "Makroen skal have et navn.",
	["The macro's name (up to 16 letters)."] = "Makroens navn (op til 16 bogstaver).",
	["The main must be one distinct guild member with no main link."] = "Vælg et andet guildmedlem som endnu ikke har et main-link.",
	["The mana cost as a percent of your maximum mana."] = "Manaprisen i procent af din maksimale mana.",
	["The map areas your characters have explored, so the others' maps can show them dimmed."] = "De kortområder dine karakterer har udforsket, så de andres kort kan vise dem nedtonet.",
	["The map fades to 30% while you move and stays solid under the mouse."] = "Kortet toner ned til 30% mens du bevæger dig, og er uigennemsigtigt under musen.",
	["The map note has changes that aren't saved."] = "Kortnoten har ændringer der ikke er gemt.",
	["The map there does not take pins."] = "Det kort kan ikke vise nåle.",
	["The micro menu and the bag bar show when you point at their spot."] = "Mikromenuen og taskelinjen vises når du peger på deres plads.",
	["The micro menu is Blizzard's again, placed by the game's Edit Mode. %s on its options page brings EldoUI's layout back."] = "Mikromenuen er Blizzards igen, placeret af spillets Edit Mode. %s på dens indstillingsside henter EldoUI's layout tilbage.",
	["The micro menu is now the %s block on the Info Bar."] = "Mikromenuen er nu blokken %s på infobjælken.",
	["The micro menu shows when you point at its spot."] = "Mikromenuen vises når du peger på dens plads.",
	["The minimap is off."] = "Minikortet er slået fra.",
	["The most buffs shown at once."] = "Det højeste antal buffs der vises på én gang.",
	["The most debuffs shown at once."] = "Det højeste antal debuffs der vises på én gang.",
	["The mount a player rides, whether you have it, and where it comes from (Mount Journal text). Out of combat only."] = "Hvilken mount en spiller rider på: om du har den og hvor den kommer fra (tekst fra mountjournalen). Kun uden for kamp.",
	["The mouse is over the unit."] = "Musen er over enheden.",
	["The mouse wheel scrolls chat windows up and down."] = "Musehjulet ruller chatvinduer op og ned.",
	["The name color while this filter matches."] = "Navnets farve mens dette filter matcher.",
	["The name line of a player's tooltip and the Target and Targeted by lines."] = "Navnelinjen i en spillers tooltip samt linjerne om mål og hvem der har spilleren som mål.",
	["The name of each entry under its icon."] = "Navnet på hvert punkt under dets ikon.",
	["The name of the next stop on the way, above the track."] = "Navnet på næste stop på vejen, over rutebjælken.",
	["The name of the spell's target under the cast bar."] = "Navnet på evnens mål under castbaren.",
	["The new-mail icon."] = "Ikonet for ny post.",
	["The note editor opens after combat."] = "Noteeditoren åbnes efter kampen.",
	["The note shows below this much mana."] = "Beskeden vises under denne mængde mana.",
	["The NPC's title (Innkeeper, Flight Master) as the game shows it. Outside instances only."] = "NPC'ens titel (Innkeeper, Flight Master) som spillet viser den. Kun uden for instanser.",
	["The off-hand imbue, while your off hand holds a weapon."] = "Off Hand-imbuen mens du har et våben i Off Hand.",
	["The offset grows as you zoom out and is gone up close, so the character stays in the middle when you zoom in."] = "Forskydningen vokser når du zoomer ud, og forsvinder helt tæt på, så karakteren bliver i midten når du zoomer ind.",
	["The oldest entries drop off after this many."] = "Når der er så mange, forsvinder de ældste poster.",
	["The one switch: off hides every EldoUI pin on the world map and the minimap. The map button, /eui mapnote and the key binding flip it too."] = "Hovedkontakten: når den er slået fra, skjules alle EldoUI-nåle på verdenskortet og minikortet. Kortknappen, /eui mapnote og genvejstasten slår den også til og fra.",
	["The one you keep up. Right-click its reminder to change it."] = "Den du holder ved lige. Højreklik på dens påmindelse for at skifte.",
	["The organizer's percent and other cuts (a fixed gold amount each)."] = "Arrangørens procentandel og andre andele (et fast guldbeløb hver).",
	["The organizer's share of the pot for new ledgers. Each ledger keeps its own cuts."] = "Arrangørens andel af potten for nye regnskaber. Hvert regnskab beholder sine egne andele.",
	["The original frames' shape: thin bars beside a round portrait, the name above them. With the Vanilla Original skin they wear the game's own frame art."] = "De oprindelige rammers form: tynde bjælker ved siden af et rundt portræt med navnet over dem. Med skinnet Vanilla Original bærer de spillets egen rammegrafik.",
	["The panels let the game show through a little. How much: General > Panel opacity."] = "Panelerne lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The part of the frame the position below refers to (Info panel needs the info panel on, General tab)."] = "Den del af rammen som placeringen herunder henviser til (Infopanel kræver at infopanelet er slået til, fanen Generelt).",
	["The Party Quests panel shows while you are in a party. /eui party shows or hides it too. Place it in move mode (Party Quests)."] = "Panelet Gruppequests vises mens du er i en gruppe. /eui party viser eller skjuler det også. Placer det i flyttetilstand (Gruppequests).",
	["The pet trainer in the capital cities teaches it to you; then teach it to your pet in Beast Training."] = "Pet-træneren i hovedstæderne lærer dig den; lær den derefter til dit pet i Beast Training.",
	["The plan names no class EldoUI knows."] = "Planen nævner ingen klasse som EldoUI kender.",
	["The plan stays saved. Pick your class in the planner to find it."] = "Planen er stadig gemt. Vælg din klasse i planlæggeren for at finde den.",
	["The Planner button and your plan on Blizzard's talent window need Blizzard UI > Spellbook and talents with Improve on."] = "Knappen Planlægger og din plan i Blizzards talentvindue kræver at Forbedr er slået til under Blizzard-UI > Evnebog og talenter.",
	["The plate belongs to your focus."] = "Nameplaten tilhører dit fokus.",
	["The plate belongs to your target."] = "Nameplaten tilhører dit mål.",
	["The plate border color while this filter matches."] = "Nameplatens kantfarve mens dette filter matcher.",
	["The plate's opacity. Normal keeps the usual opacity (and the non-target fade)."] = "Nameplatens opacitet. Normal bevarer den sædvanlige opacitet (og toningen af andre end målet).",
	["The player's class icon left of the bar."] = "Spillerens klasseikon til venstre for bjælken.",
	["The player's class icon, or the role picked in the group finder."] = "Spillerens klasseikon eller den rolle der er valgt i gruppesøgeren.",
	["The portrait"] = "Portrættet",
	["The portrait loses its color while the unit is dead, a ghost or offline. Needs Dead and offline look on the Effects tab."] = "Portrættet mister sin farve mens enheden er død, en ånd eller offline. Kræver Udseende for døde og offline på fanen Effekter.",
	["The power bar shows only while you are in combat."] = "Ressourcebjælken vises kun mens du er i kamp.",
	["The profession to plan. Your own professions show their skill."] = "Faget der skal planlægges. Dine egne fag viser din skill.",
	["The pull countdown needs a group."] = "Pull-nedtællingen kræver en gruppe.",
	["The pulsing glow round your target's plate when the target highlight is \"Pulse glow\"."] = "Den pulserende glød omkring dit måls nameplate når målfremhævningen er \"Pulserende glød\".",
	["The quest helpers skip repeatable quests, such as reputation hand-ins, so a stack is never handed in at once."] = "Quest-hjælperne springer gentagelige quests over (fx omdømme-afleveringer), så en hel stak aldrig afleveres på én gang.",
	["The quest item button glows for a few seconds when a new quest item lands on it."] = "Knappen til questgenstanden gløder i nogle sekunder når en ny questgenstand dukker op på den.",
	["The quest list beside the map gets flat scroll bars, search box and buttons."] = "Questlisten ved siden af kortet får flade rullebjælker, søgefelt og knapper.",
	["The quests you share with your party, each member's progress, and one-click Share and Ask buttons. Shares your quest progress with group members who run EldoUI, as addon messages only, never in chat."] = "De quests du deler med din gruppe, hvert medlems fremskridt og knapperne Del og Spørg med ét klik. Deler dit questfremskridt med gruppemedlemmer der bruger EldoUI, kun som addonbeskeder, aldrig i chatten.",
	["The Raid Loot window lets the game show through a little. How much: General > Panel opacity."] = "Raidloot-vinduet lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The raid marker your click puts on the rare."] = "Den raidmarkør dit klik sætter på raren.",
	["The raid target marker on this unit."] = "Raidmålmarkøren på denne enhed.",
	["The rail holds the buttons. Pick another way to gather them first."] = "Skinnen rummer knapperne. Vælg en anden måde at samle dem på først.",
	["The rank a click casts: the highest you know, or a lower one you keep on purpose (to save mana, for example)."] = "Den rang et klik caster: den højeste du kender, eller en lavere du bevidst holder dig til (for at spare mana, for eksempel).",
	["The rank after the guild name, in gray."] = "Rangen efter guildnavnet, med grå skrift.",
	["The rares you've met also show on continent maps."] = "De rares du har mødt, vises også på kontinentkort.",
	["The ready check on its own mover; ping wheel scale."] = "Klar-tjekket på sit eget flyttefelt; skala for pinghjulet.",
	["The reagent line in item tooltips is the Shopping list section on the Tooltip page."] = "Reagenslinjen i tooltips for genstande indstilles i afsnittet Indkøbsliste på siden Tooltip.",
	["The real clickable plate height Blizzard uses, in pixels. Width and height both need a value. Applied out of combat."] = "Den reelle klikbare nameplatehøjde som Blizzard bruger, i pixels. Både bredde og højde skal have en værdi. Anvendes uden for kamp.",
	["The real clickable plate size Blizzard uses, in pixels. Also the room plates take when they stack. 0 keeps the game's. Applied out of combat."] = "Den reelle klikbare nameplatestørrelse som Blizzard bruger, i pixels. Også den plads nameplates fylder når de stables. 0 bevarer spillets. Anvendes uden for kamp.",
	["The report panel lets the game show through a little. How much: General > Panel opacity."] = "Rapportpanelet lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The restock list is already empty."] = "Genopfyldningslisten er allerede tom.",
	["The restock list is empty."] = "Genopfyldningslisten er tom.",
	["The reward alert after a dungeon, scenario or world quest."] = "Belønningsadvarslen efter et dungeon, et scenarie eller en world quest.",
	["The roll line on a panel in your art style, bronze under WoW Forever."] = "Rullinjen på et panel i din grafikstil, bronze under WoW Forever.",
	["The route fades in at take-off and out on landing. Off shows and hides it at once."] = "Ruten toner ind ved afgang og ud ved landing. Når den er slået fra, vises og skjules den med det samme.",
	["The row of conditions under the text ([@mouseover], [mod:shift], [nocombat] and more). A click puts one at the cursor, into the bracket you are in."] = "Rækken af betingelser under teksten ([@mouseover], [mod:shift], [nocombat] og flere). Et klik sætter en ind ved markøren, i den klamme du står i.",
	["The rule the rows below change. Rules higher in the list win."] = "Den regel som rækkerne nedenfor ændrer. Regler højere på listen har forrang.",
	["The rule's border color and glow show while the unit casts a spell the game marks as important. The game decides, even where the flag is secret."] = "Reglens kantfarve og glød vises mens enheden caster en evne som spillet markerer som vigtig. Spillet bestemmer, også hvor markeringen er hemmelig.",
	["The rule's border color and glow show while the unit's health is under the percent below."] = "Reglens kantfarve og glød vises mens enhedens liv er under procenten nedenfor.",
	["The same for the second character or the Best of all ghost."] = "Det samme for den anden karakter eller spøgelset Bedste af alle.",
	["The same lines without a panel."] = "De samme linjer uden panel.",
	["The same prompt for resurrections. You still click Accept."] = "Den samme forespørgsel ved genoplivning. Du klikker stadig selv på Accepter.",
	["The same settings you could type with /console. EldoUI remembers your own value the first time it changes one, so Restore puts it back."] = "De samme indstillinger som du kan skrive med /console. EldoUI husker din egen værdi første gang den ændrer en indstilling, så Gendan kan sætte den tilbage.",
	["The same tooltip on the focus frame's cast bar."] = "Den samme tooltip på fokusrammens castbar.",
	["The scale as plain text (Strength=1, Agility=0.5 ...) to share."] = "Skalaen som ren tekst (Strength=1, Agility=0.5 ...) til deling.",
	["The scale in Pawn's format, ( Pawn: v1: \"Name\": ... ), for Pawn users and scale websites."] = "Skalaen i Pawns format, ( Pawn: v1: \"Navn\": ... ), til Pawn-brugere og skalahjemmesider.",
	["The scale used for this class. Each class remembers its own."] = "Den skala der bruges til denne klasse. Hver klasse husker sin egen.",
	["The score on every gear tooltip, upgrade or not."] = "Scoren i alle tooltips for udstyr, opgradering eller ej.",
	["The second line: where the friend is, or when they were last online."] = "Den anden linje: hvor vennen er, eller hvornår vedkommende sidst var online.",
	["The sender name of new chat lines. Needs the Chat module's message extras. Whisper, Reply and the right-click menu keep working."] = "Afsendernavnet på nye chatlinjer. Kræver Chat-modulets ekstra beskedfunktioner. Hvisk, Svar og højreklikmenuen virker stadig.",
	["The shaman in your group who drops it."] = "Den Shaman i din gruppe der sætter den.",
	["The shape of waypoint pins on the world map and minimap."] = "Formen på waypointnåle på verdenskortet og minikortet.",
	["The Shaper's Terrace"] = "The Shaper's Terrace",
	["The shared line ends with the game's map pin link to the place. Sharing moves your own map pin there."] = "Den delte linje slutter med spillets kortnål-link til stedet. Når du deler, flyttes din egen kortnål derhen.",
	["The shield or imbue icon of the shaman cooldown bar while it is missing (out of combat)."] = "Skjold- eller imbue-ikonet på Shaman-cooldownlinjen mens det mangler (uden for kamp).",
	["The shield the icon casts."] = "Det skjold som ikonet caster.",
	["The shop, help, report and GM windows always keep the game's own look and place."] = "Butikken, hjælpen, rapporten og GM-vinduerne beholder altid spillets eget udseende og placering.",
	["The shopping list is already empty."] = "Indkøbslisten er allerede tom.",
	["The Shopping List tracker on screen while something is pinned. Move it in move mode (Shopping List)."] = "Indkøbsliste-trackeren på skærmen mens noget er fastgjort. Flyt den i flyttetilstand (Indkøbsliste).",
	["The side each element's picker opens toward when you point at its button."] = "Den side som hvert elements vælger åbner mod når du peger på dets knap.",
	["The skill range of the herbs and ore veins in the zone."] = "Skillintervallet for urterne og malmårerne i zonen.",
	["The skill to reach. The plan starts at your skill (or 1 when you don't have the profession)."] = "Den skill du vil nå. Planen starter ved din skill (eller 1 hvis du ikke har faget).",
	["The skinning skill the zone's beasts ask for, from its level range."] = "Den Skinning-skill zonens dyr kræver, ud fra levelintervallet.",
	["The small timer on screen. Move it with /eui move."] = "Den lille tidtagning på skærmen. Flyt den med /eui move.",
	["The small zone map (Shift+M). These follow Blizzard UI > Battlefield (zone) map."] = "Det lille zonekort (Shift+M). Disse følger Blizzard-UI > Slagmarkskort (zonekort).",
	["The snapshot the buttons below use; the newest is first."] = "Det øjebliksbillede som knapperne nedenfor bruger; det nyeste står først.",
	["The sound each toast plays. The default is the game's epic loot sound."] = "Lyden som hver pop op-besked afspiller. Standard er spillets lyd for Epic loot.",
	["The sound for a dropped shield."] = "Lyden for et tabt skjold.",
	["The sound for a new ping."] = "Lyden for et nyt ping.",
	["The sound for a rare with a mount, pet, toy or set piece you don't own."] = "Lyden for en rare med en mount, et pet, et toy eller en setdel du ikke ejer.",
	["The sound for the ready check, role poll, battleground and dungeon ready pop-ups. The default is the game's ready check sound."] = "Lyden for pop op-vinduerne ved klar-tjek, rolleafstemning, og når et battleground eller dungeon er klar. Standard er spillets lyd for klar-tjek.",
	["The sound for treasures, chests and events."] = "Lyden for skatte, kister og begivenheder.",
	["The sound that plays with the unhappy pet warning. None for silence."] = "Lyden der afspilles med advarslen om utilfreds pet. Ingen for stilhed.",
	["The sound when a summon or resurrection prompt appears. None for silence."] = "Lyden når en forespørgsel om summon eller genoplivning dukker op. Vælg Ingen for stilhed.",
	["The spell this reminder asks for and a click casts; only it (or its group version) meets the reminder. Automatic: the one you cast last."] = "Den evne påmindelsen beder om, og som et klik caster; kun den (eller dens gruppeudgave) tæller. Automatisk: den du castede sidst.",
	["The spell tooltip on the target and focus cast bars, a list of the abilities each mob cast in front of you, and reputation info on reputation tokens."] = "Evnens tooltip på målets og fokusets castbars, en liste over de evner hver mob har castet foran dig, og omdømmeinfo på omdømmetokens.",
	["The spell's name on the bar."] = "Evnens navn på bjælken.",
	["The Split Timer records no levels without it."] = "Modulet Mellemtider registrerer ingen levels uden det.",
	["The strip grows with the font size; this is its smallest height."] = "Striben vokser med skriftstørrelsen; dette er dens mindste højde.",
	["The strip lets the game show through a little. How much: General > Panel opacity."] = "Strimlen lader spillet skinne en smule igennem. Hvor meget: Generelt > Panelopacitet.",
	["The strip sits above the window like a title bar, with an accent border."] = "Striben sidder over vinduet som en titellinje, med accentkant.",
	["The switch controls HandyNotes"] = "Kontakten styrer HandyNotes",
	["The tab above the map (right-click for Blizzard's options) in the EldoUI look."] = "Fanen over kortet (højreklik for Blizzards indstillinger) i EldoUI-udseendet.",
	["The talent loadout asks for %d ranks of %s, more than it has. Make the string again on the calculator site."] = { one = "Talentloadouten beder om %d rangtrin i %s, mere end talentet har. Lav strengen igen på beregnerens side.", other = "Talentloadouten beder om %d rangtrin i %s, flere end talentet har. Lav strengen igen på beregnerens side." },
	["The talent part of this Wowhead link isn't in a form EldoUI reads."] = "Talentdelen af Wowhead-linket er ikke i et format som EldoUI kan læse.",
	["The text in the middle of the screen after a screenshot."] = "Teksten midt på skærmen efter et skærmbillede.",
	["the text is too long"] = "teksten er for lang",
	["The text of the tag in the quest window and in quest tooltips, e.g. New or New in Forever."] = "Teksten i mærket i questvinduet og i questtooltips, fx Ny eller Ny i Forever.",
	["The theme font for tooltip text. Off keeps the game font."] = "Temaets skrifttype til tooltiptekst. Når den er slået fra, beholdes spillets skrifttype.",
	["The theme font, colors and line numbers."] = "Temaets skrifttype, farver og linjenumre.",
	["The threat border on these plates, in the game's threat color. As on the Effects tab keeps your normal setting."] = "Aggrokanten på disse nameplates i spillets aggrofarve. \"Som på fanen Effekter\" bevarer din normale indstilling.",
	["The ticks already follow the role set."] = "Tikkene følger allerede rollesættet.",
	["The time before each line."] = "Tiden foran hver linje.",
	["The timer turns green when you are ahead of your reference and red when behind. Times come from /played, recorded by the Alts module."] = "Tidtagningen bliver grøn når du er foran din reference, og rød når du er bagud. Tiderne kommer fra /played og registreres af Alts-modulet.",
	["The toast in a thin frame line that matches the WoW Forever art style."] = "Pop op-beskeden i en tynd rammelinje der passer til WoW Forever-grafikstilen.",
	["The toast's background; Panel follows your art style."] = "Pop op-beskedens baggrund; Panel følger din grafikstil.",
	["The tooltip border turns green when the item is an upgrade."] = "Tooltippens kant bliver grøn når genstanden er en opgradering.",
	["The totem buffs a shaman's totems give you. The group dims a step for each shaman in your party who is out of range, and fully when all of them are."] = "De totembuffs som en Shamans totems giver dig. Gruppen nedtones et trin for hver Shaman i din gruppe som er uden for rækkevidde, og helt når de alle er det.",
	["The totem's picture on totem plates."] = "Totemmets billede på totemnameplates.",
	["The totems each shaman carries and their Ankh count. Yours comes from your bags; another shaman's when they click Share mine."] = "De totems hver Shaman bærer på, og deres antal Ankhs. Dine kommer fra dine tasker; en anden Shamans når vedkommende klikker på Del mine.",
	["The totems each shaman carries, their Ankh count, shield, weapon imbues and mana in the Ready Check Report. Yours is read out of combat; Share mine sends yours along."] = "De totems hver Shaman bærer på, deres antal Ankhs, skjold, våben-imbues og mana i Klar-tjek-rapporten. Dine læses uden for kamp; Del mine sender dine med.",
	["The tracker is hidden (Hide switch or its box in move mode), so these rules apply once it shows again."] = "Trackeren er skjult (Skjul-kontakten eller dens boks i flyttetilstand), så disse regler gælder først når den vises igen.",
	["The tracker shows at most this many lines; the planner window shows them all."] = "Trackeren viser højst så mange linjer; planlæggerens vindue viser dem alle.",
	["The tracker turns see-through or invisible but is never hidden, so quest item buttons keep working in combat. Hover it to see it fully."] = "Trackeren bliver gennemsigtig eller usynlig, men skjules aldrig, så knapper til questgenstande stadig virker i kamp. Hold musen over den for at se den helt.",
	["The tracker's background: a full panel in your art style, a see-through one, or text only."] = "Trackerens baggrund: et fuldt panel i din grafikstil, et gennemsigtigt panel eller kun tekst.",
	["The Trade log window, newest first (also /eui trades and the link in chat)."] = "Vinduet Handelslog, nyeste først (også /eui trades og linket i chatten).",
	["The trade window. Its size (mouse wheel on the title bar), dragging and the resets are on the Move windows page, with every other Blizzard window; where it opens is its mover in move mode (/eui move)."] = "Byttevinduet. Størrelsen (musehjulet på titellinjen), trækning og nulstillingerne findes på siden Flyt vinduer sammen med alle andre Blizzard-vinduer; hvor det åbner, styres af dets flyttefelt i flyttetilstand (/eui move).",
	["The Training tab lists what your class trainer can teach you now and at later levels, with the cost. It only shows the list: you still learn at the trainer."] = "Fanen Træning viser hvad din klassetræner kan lære dig nu og på senere levels, med prisen. Den viser kun listen: du lærer stadig evnerne hos træneren.",
	["The travel list opens when combat ends."] = "Rejselisten åbner når kampen er slut.",
	["The trees, the next point and the Learn buttons follow this plan."] = "Træerne, det næste point og Lær-knapperne følger denne plan.",
	["The unit is behind your camera."] = "Enheden er bag dit kamera.",
	["The unit is casting or channeling a spell right now."] = "Enheden caster eller channeler en evne lige nu.",
	["The unit's combat state, when the game shows it."] = "Enhedens kampstatus når spillet viser den.",
	["The unit's crowd control effect (stun, fear, sheep ...) left of the plate, picked by Blizzard's filter."] = "Enhedens CC-effekt (stun, fear, sheep ...) til venstre for nameplaten, valgt af Blizzards filter.",
	["The unit's level in a small badge, colored by how hard it is for you."] = "Enhedens level i et lille mærke, farvet efter hvor svær den er for dig.",
	["The unit's portrait left of the bar."] = "Enhedens portræt til venstre for bjælken.",
	["The unit's raid marker (skull, cross ...) in front of the spell name."] = "Enhedens raidmarkør (kranie, kryds ...) foran evnenavnet.",
	["The vendor price in the corner of each reward; the most valuable choice in your accent color, unless Upgrades already marks quest rewards. You still pick."] = "Købmandsprisen i hjørnet af hver belønning; det mest værdifulde valg i din accentfarve, medmindre Opgraderinger allerede markerer questbelønninger. Du vælger stadig selv.",
	["The view, create, holiday, raid and picker windows next to the calendar get the EldoUI look too."] = "Vinduerne for visning, oprettelse, helligdage, raid og valg ved siden af kalenderen får også EldoUI-udseendet.",
	["The water totem the water button drops."] = "Den vandtotem som vandknappen sætter.",
	["The way the buttons fill the bin, then the way the next row goes. The bin opens on that side of its button. Automatic fills rows to the right and follows Bin side."] = "Den retning knapperne fylder samlekassen i, og derefter den retning den næste række går. Samlekassen åbnes på den side af sin knap. Automatisk fylder rækker mod højre og følger Samlekassens side.",
	["The waypoint's title under the arrow."] = "Waypointets titel under pilen.",
	["The whole frame"] = "Hele rammen",
	["The window lets the game show through a little. How much: General > Panel opacity."] = "Vinduet lader spillet skinne en smule igennem. Hvor meget: Generelt > Panelopacitet.",
	["The world map's top right button shows or hides EldoUI's pins: click for groups, Shift-click for all. Alt-right-click the map to add a note."] = "Verdenskortets knap øverst til højre viser eller skjuler EldoUI's nåle: klik for grupper, Shift-klik for alle. Alt-højreklik på kortet for at tilføje en note.",
	["The world map, flight map and taxi window go back to Blizzard's place."] = "Verdenskortet, flyvekortet og flyverutevinduet vender tilbage til Blizzards placering.",
	["The x on a listing dismisses it (by its leader). Bring back on the filter bar shows them again at any time."] = "Krydset på et opslag afviser det (ud fra lederen). Med Hent tilbage på filterbjælken kan du altid få dem frem igen.",
	["The XP bar disappears at the level cap; the reputation bar takes its place."] = "XP-bjælken forsvinder ved levelgrænsen; omdømmebjælken tager dens plads.",
	["The XP tooltip shows the XP still needed to reach the level cap and, with session statistics on, the time at this session's pace (rested XP and finished quests count as a head start)."] = "XP-tooltippen viser hvor meget XP der mangler til levelgrænsen og, med sessionsstatistik slået til, tiden med denne sessions tempo (udhvilet XP og færdige quests tæller som et forspring).",
	["The XP tooltip shows XP gained this session, XP per hour and the time to the next level."] = "XP-tooltippen viser XP optjent i denne session, XP pr. time og tiden til næste level.",
