	["Turns off the bright glow and shine when an alert appears."] = "Slår den skarpe glød og glans fra når en advarsel dukker op.",
	["Turns off the gray screen while dead, the nether effect, and drunken haze. Off puts your own game settings back."] = "Slår den grå dødsskærm, nethereffekten og beruselsessløret fra. Fra gendanner dine egne spilindstillinger.",
	["Turns on the Blizzard UI switch for the bag bar with Move and scale."] = "Slår Blizzard-UI-kontakten for taskelinjen til med Flyt og skaler.",
	["Turns on the Blizzard UI switch for the micro menu with Move and scale."] = "Slår Blizzard-UI-kontakten for mikromenuen til med Flyt og skaler.",
	["Turns on the Blizzard UI switch for the minimap buttons with Move."] = "Slår Blizzard-UI-kontakten for minikortknapperne til med Flyt.",
	["Turns on the Blizzard UI switch for the minimap with Replace."] = "Slår Blizzard-UI-kontakten for minikortet til med Erstat.",
	["Turns on the Blizzard UI switch for this element with Replace, so only EldoUI's bars show."] = "Slår Blizzard-UI-kontakten for dette element til med Erstat, så kun EldoUI's bjælker vises.",
	["Turns the ring: 0 puts the first entry (or the middle of an arc) at the top, clockwise."] = "Drejer ringen: 0 sætter det første punkt (eller midten af en bue) øverst, med uret.",
	["Turns your party into a raid, or a raid of five or fewer back into a party."] = "Gør din gruppe til et raid, eller et raid med fem eller færre tilbage til en gruppe.",
	["Turns your party into a raid, or a small raid back into a party (group leader)."] = "Gør din gruppe til et raid, eller et lille raid tilbage til en gruppe (gruppeleder).",
	["Tutorials and help tips off (game settings; Blizzard default puts yours back)."] = "Vejledninger og hjælpetips fra (spilindstillinger; Blizzard-standard sætter dine tilbage).",
	["Tutorials off"] = "Vejledninger fra",
	["Twilight slim"] = "Twilight slim",
	["Two"] = "To",
	["Two buttons on the preview: take everything off the model, or show your target's look. Blizzard's Reset button stays."] = "To knapper på forhåndsvisningen: tag alt af modellen, eller vis dit måls udseende. Blizzards Reset-knap bliver.",
	["Two characters level by level: time per level, total played at each level-up and the difference."] = "To karakterer level for level: tid pr. level, samlet spilletid ved hvert level-up og forskellen.",
	["Two columns"] = "To kolonner",
	["Two columns of rows, for vendors with long lists."] = "To kolonner af rækker, til købmænd med lange lister.",
