	["Two-handed leveling"] = "Leveling med tohåndsvåben",
	["Type /eui pull, /eui pull 8 or /eui pull cancel."] = "Skriv /eui pull, /eui pull 8 eller /eui pull cancel.",
	["Type a character name first, for example Name-Realm."] = "Skriv først et karakternavn, for eksempel Navn-Realm.",
