	["Type a spell ID and press Enter."] = "Skriv et evne-ID, og tryk Enter.",
	["Type a spell or item name. Empty shows every icon the game offers."] = "Skriv et evne- eller genstandsnavn. Tomt viser alle ikoner som spillet tilbyder.",
	["Type a value and press Enter or Set. The game checks it; a value it refuses is not kept."] = "Skriv en værdi, og tryk Enter eller Angiv. Spillet tjekker den; en værdi som det afviser, gemmes ikke.",
