	["Type coordinates, like 45.2 63.8 or Elwynn Forest 41 65 Inn."] = "Skriv koordinater, fx 45.2 63.8 eller Elwynn Forest 41 65 Inn.",
	["Type part of a name or help text and press Enter."] = "Skriv en del af et navn eller en hjælpetekst, og tryk Enter.",
	["Type the frame name of an addon button the bin does not find by itself, then press Enter. The game's own buttons and protected buttons stay where they are."] = "Skriv rammenavnet på en addonknap som samlekassen ikke selv finder, og tryk på Enter. Spillets egne knapper og beskyttede knapper bliver hvor de er.",
