	["Well Fed"] = "Well Fed",
	["What a middle-click on the map opens."] = "Hvad et midterklik på kortet åbner.",
	["What a restore starts with"] = "Hvad en gendannelse starter med",
	["What each member is missing."] = "Hvad hvert medlem mangler.",
	["What EldoUI may do with Blizzard's tooltips is set on the Blizzard UI page. These settings shape what each switch does."] = "Hvad EldoUI må gøre med Blizzards tooltips, indstilles på Blizzard-UI-siden. Disse indstillinger bestemmer hvad hver kontakt gør.",
	["What EldoUI may do with each window is set on the Blizzard UI page. The settings below work once its switch is on."] = "Hvad EldoUI må gøre med hvert vindue, indstilles på Blizzard-UI-siden. Indstillingerne nedenfor virker når vinduets kontakt er slået til.",
	["What EldoUI shows for you. Empty shows Player. At most 24 letters."] = "Det EldoUI viser for dig. Tom viser Spiller. Højst 24 bogstaver.",
	["What happens to items that don't match the search box or the filters: left out of the list, or shown faded so you still see the whole vendor."] = "Hvad der sker med genstande der ikke matcher søgefeltet eller filtrene: de udelades fra listen, eller de vises tonet ned så du stadig ser hele købmandens udvalg.",
	["What is on your bars now is saved as a snapshot first, so you can go back."] = "Det der er på dine linjer nu, gemmes først som et øjebliksbillede, så du kan gå tilbage.",
	["What it checks"] = "Hvad den tjekker",
	["What shows behind the inspected character: Blizzard's picture, or a plain backdrop in your art style's panel color. Default: plain."] = "Hvad der vises bag den inspicerede karakter: Blizzards billede eller en ensfarvet baggrund i panelfarven fra din grafikstil. Standard: ensfarvet.",
	["what the game reports about nameplate size, stacking and effects"] = "hvad spillet rapporterer om nameplatestørrelse, stabling og effekter",
	["What the items each side offers sell for at a vendor, plus the gold offered."] = "Hvad genstandene som hver side tilbyder, sælges for hos en købmand, plus det tilbudte guld.",
	["What the name text shows, e.g. [classcolor][name:medium][close]. The Text tags page lists every tag with a live preview."] = "Hvad navneteksten viser, fx [classcolor][name:medium][close]. Siden Teksttags viser alle tags med en direkte forhåndsvisning.",
	["What the setting is now."] = "Indstillingens nuværende værdi.",
	["What the text on each bar shows."] = "Hvad teksten på hver bjælke viser.",
	["What the Training block on the info bar shows (add it under Info Bar)."] = "Hvad blokken Træning i Infobjælken viser (tilføj den under Infobjælke).",
	["What this trainer teaches"] = "Hvad denne træner lærer fra sig",
	["what to check"] = "hvad der tjekkes",
	["What to remind"] = "Påmind om",
	["What your class trainer can teach you now and later, with costs, totals, an ignore list, weapon skills and pet training. Its own window, a spellbook tab and an info bar block."] = "Hvad din klassetræner kan lære dig nu og senere, med priser, totaler, en ignoreringsliste, våbenskills og pettræning. Sit eget vindue, en fane i evnebogen og en blok i Infobjælken.",
	["When"] = "Når",
	["When a ready check starts, one panel shows what each member is missing: class buffs, flask or elixir, food, and durability and version from members who share them."] = "Når et klar-tjek starter, viser ét panel hvad hvert medlem mangler: klassebuffs, flask eller eliksir, mad samt holdbarhed og version fra medlemmer der deler dem.",
	["When an NPC's only option is their shop and they have no quest for you, the shop opens straight away. Off by default."] = "Når en NPC's eneste valgmulighed er butikken og NPC'en ikke har nogen quest til dig, åbner butikken med det samme. Slået fra som standard.",
	["When flagged for PvP"] = "Når PvP-flagget",
	["When hidden"] = "Når den er skjult",
	["When I lead or assist"] = "Når jeg er leder eller assistent",
	["When it opens"] = "Hvornår det åbner",
	["When it shows"] = "Hvornår den vises",
	["When no reward is an upgrade, a coin marks the one that sells for most."] = "Når ingen belønning er en opgradering, markerer en mønt den der kan sælges for mest.",
	["When several colors apply, the first one in this list wins:"] = "Når flere farver passer, vinder den første i denne liste:",
	["When someone who isn't a friend asks to join your group, the request is declined. Suggestions from your group members still ask you. Off by default."] = "Når nogen der ikke er din ven, beder om at blive med i din gruppe, afvises anmodningen. Forslag fra dine gruppemedlemmer spørger stadig dig. Slået fra som standard.",
	["When the cast fails or is interrupted, the bar stays a moment in the interrupted color with the reason."] = "Når castet mislykkes eller bliver afbrudt, bliver bjælken et øjeblik stående i farven ved afbrydelse med årsagen.",
	["When the cast goes off, the bar stays a moment in the success color."] = "Når castet går igennem, bliver bjælken et øjeblik stående i succesfarven.",
	["When the game says this character already killed or looted it (or did it today), no card and no sound; it is still listed under This session. Other cards show Already done."] = "Når spillet siger at denne karakter allerede har dræbt eller lootet den (eller klaret den i dag), kommer der intet kort og ingen lyd; den står stadig under Denne session. Andre kort viser Allerede klaret.",
	["When the group ends, a card with how long you grouped and the quests you turned in while a member was on them too."] = "Når gruppen opløses: et kort med hvor længe I var i gruppe, og de quests du afleverede mens et medlem også var i gang med dem.",
	["When the panel opens by itself as a ready check starts. With Never it only opens from /eui readycheck."] = "Hvornår panelet åbner af sig selv når et klar-tjek starter. Med Aldrig åbner det kun fra /eui readycheck.",
	["When this part of the info area shows."] = "Hvornår denne del af infoområdet vises.",
	["When you enter the world, a dungeon, a raid or a battleground, the bar switches to the loadout picked below (out of combat). This acts for you. Off by default."] = "Når du kommer ind i verden, et dungeon, et raid eller en battleground, skifter linjen til det loadout der er valgt nedenfor (uden for kamp). Dette handler på dine vegne. Slået fra som standard.",
	["When you learn a spell, the game places it on a free action button by itself (game setting). EldoUI keeps it off while new spells go to their key automatically."] = "Når du lærer en evne, placerer spillet den selv på en ledig handlingsknap (spilindstilling). EldoUI holder den slået fra mens nye evner automatisk kommer på deres tast.",
	["When you place the game's own map pin (Ctrl+click on the map), it becomes a waypoint too."] = "Når du sætter spillets egen kortnål (Ctrl+klik på kortet), bliver den også et waypoint.",
	["When you play alone: a reminder while you have no Soulstone on you. Off by default."] = "Når du spiller alene: en påmindelse mens du ikke har nogen Soulstone på dig. Slået fra som standard.",
	["When you target or point at a rare creature outdoors, remember where you stood, its name and when. Nothing is kept in dungeons, raids, battlegrounds or arenas."] = "Når du har en rare som mål eller peger på den udendørs, huskes hvor du stod, dens navn og hvornår. Intet gemmes i dungeons, raids, battlegrounds eller arenaer.",
	["Whenever you gain reputation with a faction, the bar switches to that faction (Blizzard's \"Show as experience bar\" setting)."] = "Når du får omdømme hos en fraktion, skifter bjælken til den fraktion (Blizzards indstilling for at vise en fraktion som erfaringsbjælke).",
	["Where"] = "Hvor",
	["Where a menu appears when you press its key."] = "Hvor en menu dukker op når du trykker på dens tast.",
	["Where a second row goes."] = "Hvor en anden række placeres.",
	["Where each flight master flies, learned from your flight maps."] = "Hvor hver flyvemester flyver hen, lært fra dine flyvekort.",
	["Where hostile, neutral and friendly colors come from. Colors page: the Reaction colors the unit frames use too. Own colors: the three below, on nameplates only."] = "Hvor fjendtlige, neutrale og venlige farver kommer fra. Siden Farver: de reaktionsfarver som unitframes også bruger. Egne farver: de tre nedenfor, kun på nameplates.",
	["Where it was seen"] = "Hvor den blev set",
	["Where rares are found"] = "Hvor rares findes",
	["Where the bin opens. Automatic opens beside the map on the side that faces the middle of the screen, or below it where there is no room, and always stays on the screen."] = "Hvor samlekassen åbnes. Med Automatisk åbnes den ved siden af kortet på den side der vender mod skærmens midte, eller under kortet hvor der ikke er plads, og den bliver altid på skærmen.",
	["Where the chat input box sits: Classic shows it only while you type, IM keeps it under the chat window."] = "Hvor chatfeltet sidder: Classic viser det kun mens du skriver, IM holder det under chatvinduet.",
	["Where the eye sits when it is attached to the minimap (Blizzard UI: Queue status eye)."] = "Hvor øjet sidder når det er fastgjort til minikortet (Blizzard-UI: Køstatus-øje).",
	["Where the health text sits inside the bar."] = "Hvor livsteksten sidder inde i bjælken.",
	["Where the info strip sits."] = "Hvor infostriben sidder.",
	["Where the mouse points on the map."] = "Hvor musen peger på kortet.",
	["Where the name sits. In the info panel: on the left of the strip or name bar (General tab), else on the health bar."] = "Hvor navnet sidder. I infopanelet: til venstre i strimlen eller navnebjælken (fanen Generelt), ellers på livsbjælken.",
	["Where the number sits on the slot."] = "Hvor tallet sidder på pladsen.",
	["Where the path works best: leveling, dungeons, raids, PvP or farming."] = "Hvor stien virker bedst: leveling, dungeons, raids, PvP eller farming.",
	["Where the private auras sit around the frame."] = "Hvor de private auraer sidder omkring rammen.",
	["Where the second bar goes when more than one shows. With upright bars: Upwards adds them to the right, Downwards to the left."] = "Hvor den anden bjælke placeres når der vises mere end én. Med lodrette bjælker: Opad tilføjer dem til højre, Nedad til venstre.",
	["Where the spell tooltip opens."] = "Hvor evnens tooltip åbner.",
	["Where the stack count sits on the icon."] = "Hvor stakantallet sidder på ikonet.",
	["Where the threat border of the Effects tab shows: round the whole frame or only round the portrait."] = "Hvor aggrokanten fra fanen Effekter vises: rundt om hele rammen eller kun rundt om portrættet.",
	["Where the time sits on the icon."] = "Hvor tiden sidder på ikonet.",
	["Where the unit's name sits above the bar."] = "Hvor enhedens navn sidder over bjælken.",
	["Where they show"] = "Hvor de vises",
	["Where you are"] = "Hvor du er",
	["Where you are on the map you are looking at."] = "Hvor du er på det kort du kigger på.",
	["Where you can set your hearthstone."] = "Hvor du kan sætte din Hearthstone.",
	["Where you play: Recommended build copies the suggested path for it and your role."] = "Hvor du spiller: Anbefalet build kopierer den foreslåede sti til det sted og din rolle.",
	["Where you reach your bank."] = "Hvor du har adgang til din bank.",
	["Where your detached cast bar sits: on the Player Cast Bar mover, or hung under or above the Cooldown Manager so it moves with it (the mover is then not used)."] = "Hvor din løsrevne castbar sidder: på flyttefeltet Spillerens castbar, eller hængt under eller over Cooldown Manager, så den flytter med (flyttefeltet bruges så ikke).",
	["Whether a member has a flask or at least one elixir up."] = "Om et medlem har en flask eller mindst én eliksir aktiv.",
	["Whether a member is Well Fed."] = "Om et medlem er Well Fed.",
	["Which beast teaches which rank comes from the Loot Guide's data folder, EldoUI_LootData."] = "Hvilket dyr der lærer hvilken rang, kommer fra Loot Guide-datamappen, EldoUI_LootData.",
	["Which buffs"] = "Hvilke buffs",
	["Which buffs on enemies to show, picked by Blizzard's own filters. Defensives: big defensive cooldowns. Size and number are set per type."] = "Hvilke buffs på fjender der vises, valgt af Blizzards egne filtre. Defensive evner: store defensive cooldowns. Størrelse og antal indstilles pr. type.",
	["Which characters"] = "Hvilke karakterer",
	["Which corner the first button sits in and which way new buttons and rows are added."] = "Hvilket hjørne den første knap sidder i og hvilken vej nye knapper og rækker tilføjes.",
	["Which debuffs"] = "Hvilke debuffs",
	["Which end of the bar the icon sits at."] = "Hvilken ende af bjælken ikonet sidder i.",
	["Which instances count for the instance settings (the gear button next to Show)."] = "Hvilke instanser der tæller med for instansindstillingerne (tandhjulsknappen ved Vis).",
	["Which items to keep in your bags, and how many."] = "Hvilke genstande du vil beholde i dine tasker, og hvor mange.",
	["Which menu the rows below change."] = "Hvilken menu rækkerne nedenfor ændrer.",
	["Which of your talent groups is active."] = "Hvilken af dine talentgrupper der er aktiv.",
	["Which plate type the test plate shows. It uses your own character's name and health."] = "Hvilken nameplatetype testnameplaten viser. Den bruger din egen karakters navn og liv.",
	["Which plates show"] = "Hvilke nameplates der vises",
	["Which quest"] = "Hvilken quest",
	["Which role's spells the bar starts with. Automatic follows the Role page, else your talents. Picking a set replaces your own ticks below."] = "Hvilken rolles evner linjen starter med. Automatisk følger siden Rolle, ellers dine talenter. Vælger du et sæt, erstatter det dine egne flueben nedenfor.",
	["Which saved price the leveling plan uses for a reagent: EldoUI's auction prices (from your searches), what a vendor charges (seen at vendors), or the lower of the two."] = "Hvilken gemt pris levelplanen bruger til et reagens: EldoUI's auktionspriser (fra dine søgninger), hvad en købmand tager (set hos købmænd) eller den laveste af de to.",
	["Which shield"] = "Hvilket skjold",
	["Which side of the bars the value tags sit on."] = "Hvilken side af bjælkerne værdimærkerne sidder på.",
	["Which side of the cast bar the spell icon sits on."] = "Hvilken side af castbaren evneikonet sidder på.",
	["Which side of the frame (or of the other block) they sit on."] = "Hvilken side af rammen (eller af den anden blok) de sidder på.",
	["Which tooltips stay hidden while you are in combat."] = "Hvilke tooltips der er skjult mens du er i kamp.",
	["Which volume slider controls these sounds. Default follows General > Sound channel."] = "Hvilken lydstyrkeskyder der styrer disse lyde. Standard følger Generelt > Lydkanal.",
	["Which way a row fills."] = "Hvilken vej en række fyldes.",
	["Which way the health bar fills."] = "Hvilken vej livsbjælken fyldes.",
	["Which way the list of frames grows from its mover."] = "Hvilken vej listen af rammer vokser fra sit flyttefelt.",
	["Which Wowhead the address points to. /eui wowhead (or a macro with it on a key) works on whatever the tooltip shows."] = "Hvilken Wowhead adressen peger på. /eui wowhead (eller en makro med kommandoen på en tast) virker på det som tooltippen viser.",
	["While a unit casts, its cast bar draws over the plates around it, so stacked casters stay readable."] = "Mens en enhed caster, tegnes dens castbar over nameplates omkring den, så stablede casters er læsbare.",
	["While Blizzard's Quick Keybind window is open, hover an EldoUI button and press a key to bind it, as in EldoUI keybind mode. Blizzard's Okay keeps the keys, Cancel drops them."] = "Mens Blizzards Quick Keybind-vindue er åbent, kan du holde musen over en EldoUI-knap og trykke på en tast for at tildele den, ligesom i EldoUI-genvejstasttilstand. Blizzards Okay beholder tasterne, Cancel kasserer dem.",
	["While leveling, out of combat: a note when no XP bonus is running, such as the Well Fed XP Boost from XP food."] = "Mens du leveler, uden for kamp: en note når ingen XP-bonus kører, fx Well Fed XP Boost fra XP-mad.",
	["While the bar holds, the spell name changes to Done, Interrupted or Failed."] = "Mens bjælken bliver stående, skifter evnenavnet til Færdig, Afbrudt eller Mislykkedes.",
	["While the game's color-blind mode is on, add a word after the level in the quest log, quest tracker and quest giver lists, like [24 hard]. On by default."] = "Når spillets farveblindtilstand er slået til, tilføjes et ord efter levelet i questloggen, questtrackeren og questgiverlister, fx [24 svær]. Slået til som standard.",
	["While you cast, the part of your power the spell will cost is marked on the bar (your own spells; costs the game keeps secret show nothing)."] = "Mens du caster, markerer bjælken den del af din ressource som evnen vil koste (dine egne evner; priser som spillet holder hemmelige, viser ingenting).",
	["Whisper history cleared."] = "Hviskehistorikken er ryddet.",
	["Whispers (and, if you like, guild and group chat) in their own messenger windows, with contact info and a history browser."] = "Hvisken (og efter ønske guild- og gruppechat) i deres egne messengervinduer med kontaktinfo og en historikoversigt.",
	["White, or class color for players and reaction color for NPCs."] = "Hvid, eller klassefarve for spillere og reaktionsfarve for NPC'er.",
	["Who"] = "Hvem",
	["Who asked and a countdown, with Blizzard's own Ready / Not ready buttons. You always answer yourself."] = "Hvem der spurgte og en nedtælling med Blizzards egne knapper Klar / Ikke klar. Du svarer altid selv.",
	["Who is this?"] = "Hvem er det?",
	["Who it reaches shows again after combat."] = "Hvem den når, vises igen efter kampen.",
	["Who list"] = "Spillersøgning",
	["Who list skin"] = "Skin på spillersøgningen",
	["Who sees the bar: everyone, anyone in a group, anyone in a raid, or only the leader and assists. Leader or assist is checked out of combat. The Visibility rules below apply on top."] = "Hvem ser bjælken: alle, alle i en gruppe, alle i et raid eller kun lederen og assistenterne. Leder eller assistent tjekkes uden for kamp. Synlighedsreglerne nedenfor gælder oveni.",
	["Who shares the pot. Buyers join by themselves."] = "Hvem der deler potten. Købere kommer selv med.",
	["Who soft-reserved an item (SR) and who has it on That's My BiS (TMB), from the lists you imported under Raid Loot."] = "Hvem der har soft-reserveret en genstand (SR) og hvem der har den på That's My BiS (TMB), ud fra de lister du har importeret under Raidloot.",
	["Who you trade with"] = "Hvem du handler med",
	["Who your totems reach"] = "Hvem dine totems når",
	["Whole body"] = "Hele kroppen",
	["Whole night"] = "Hele aftenen",
	["Whole numbers, one or two decimals."] = "Hele tal, én eller to decimaler.",
	["Whole plan"] = "Hele planen",
	["Whose snapshots to list. A snapshot from another character copies that setup to this one; spells this character doesn't know are skipped."] = "Hvis øjebliksbilleder der skal vises. Et øjebliksbillede fra en anden karakter kopierer den opsætning til denne; evner som denne karakter ikke kender, springes over.",
	["Whose territory the zone is: yours (green), the other faction's (red) or contested (orange)."] = "Hvis territorium zonen er: dit (grøn), den anden fraktions (rød) eller omstridt (orange).",
	["Why these talents, when to change, what to keep on your bars."] = "Hvorfor disse talenter, hvornår du skal skifte, og hvad du skal have på dine handlingslinjer.",
	["Wide frames with the current health value, easy to read next to party and raid frames."] = "Brede rammer med den nuværende livsværdi, nemme at læse ved siden af gruppe- og raidrammer.",
	["Wide log"] = "Bred log",
	["Widget and alternate power text in the EldoUI font. Sizes and colors stay Blizzard's."] = "Widgettekst og tekst for alternativ ressource i EldoUI-skrifttypen. Størrelser og farver er stadig Blizzards.",
	["Widgets"] = "Widgets",
	["Width and height of each aura icon in this row."] = "Bredde og højde på hvert auraikon i denne række.",
	["Width and height of each square on the party frames."] = "Bredde og højde på hver firkant på grupperammerne.",
	["Width and height of each totem cooldown icon."] = "Bredde og højde på hvert totem-cooldownikon.",
	["Width and height of the EldoUI minimap (Replace)."] = "Bredde og højde på EldoUI-minikortet (Erstat).",
	["Width in combat"] = "Bredde i kamp",
	["Width of a newly opened window. Drag the corner to resize one."] = "Bredden på et nyåbnet vindue. Træk i hjørnet for at ændre et vindues størrelse.",
	["Width of an edge or own-position bar. Auto makes it about as wide as the frame."] = "Bredde på en kantbjælke eller en bjælke med egen placering. Auto gør den omtrent lige så bred som rammen.",
	["Width of each healer row."] = "Bredden på hver healerrække.",
	["Width of each timer bar. Auto makes it as wide as the frame."] = "Bredde på hver tidsbjælke. Auto gør den lige så bred som rammen.",
	["Width of each toast."] = "Bredden på hver pop op-besked.",
	["Width of one column of rows in pixels."] = "Bredden på én kolonne af rækker i pixels.",
	["Width of one tile in pixels; long names wrap onto a second line."] = "Bredden på ét felt i pixels; lange navne ombrydes til en anden linje.",
	["Width of the bar, icon included."] = "Bjælkens bredde, inklusive ikon.",
	["Width of the card. The style presets set it."] = "Kortets bredde. Stilpresettene sætter den.",
	["Width of the health bar in pixels."] = "Livsbjælkens bredde i pixels.",
	["Width of the portrait box. Square makes it as wide as the frame is tall."] = "Portrætboksens bredde. Firkant gør den lige så bred som rammen er høj.",
	["Width of the route in pixels. Move it with /eui move (\"Flight Timer\")."] = "Rutens bredde i pixels. Flyt den med /eui move (\"Flyvenedtælling\").",
	["Width of the sent log beside the mailbox."] = "Bredden på afsendelsesloggen ved siden af postkassen.",
	["Width of the Shopping List tracker."] = "Bredden på indkøbsliste-trackeren.",
	["Width of the timer."] = "Bredden på tidtagningen.",
	["Width of the window when it stands alone."] = "Vinduets bredde når det står alene.",
	["Window only"] = "Kun vindue",
	["Window row height"] = "Rækkehøjde i vinduet",
	["Window Skins"] = "Vinduesskins",
	["Window visibility"] = "Vinduets synlighed",
	["wish"] = "ønske",
	["With action targeting or a gamepad, the enemy the game picked for you gets the mouse-over look."] = "Med action targeting eller gamepad får den fjende, spillet har valgt for dig, samme fremhævning som når musen er over.",
	["With Alt"] = "Med Alt",
	["With Ctrl"] = "Med Ctrl",
	["With HandyNotes installed, it becomes a group in the map button's menu, so one click hides EldoUI's and HandyNotes' pins together."] = "Når HandyNotes er installeret, bliver den en gruppe i kortknappens menu, så ét klik skjuler både EldoUI's og HandyNotes' nåle.",
	["With My Adventure on, show how long you have grouped with the player and when you met, from the journal's Fellowship."] = "Med My Adventure slået til vises hvor længe du har været i gruppe med spilleren, og hvornår I mødtes, fra journalens Rejsefæller.",
	["With Shift"] = "Med Shift",
	["With Skin on: hide Blizzard's frame art and put flat EldoUI boxes behind the bars."] = "Med Skin slået til: skjul Blizzards rammegrafik, og læg flade EldoUI-bokse bag bjælkerne.",
	["With the EldoUI skin on: unread letters show the sender in the accent color, read ones in gray."] = "Med EldoUI-skinnet slået til: ulæste breve viser afsenderen i accentfarven, læste i gråt.",
	["With the new rank the macro would have %d characters, and a macro holds %d. Shorten it first."] = "Med den nye rang ville makroen have %d tegn, og en makro kan rumme %d. Gør den kortere først.",
	["With your best discount"] = "Med din bedste rabat",
	["Without a food dropped on the button, use the lowest level food in your bags that your pet eats and still enjoys."] = "Når der ikke er trukket mad over på knappen, bruges maden med det laveste level i dine tasker som dit pet spiser og stadig kan lide.",
	["Without discount"] = "Uden rabat",
	["World boss"] = "Verdensboss",
	["World boss · Level %s"] = "Verdensboss · Level %s",
	["World bosses"] = "Verdensbosser",
	["World bosses and bosses."] = "Verdensbosser og bosser.",
	["World bosses are quiet everywhere."] = "Verdensbosser er stille overalt.",
	["World map"] = "Verdenskort",
	["World map only"] = "Kun verdenskort",
	["World map pins"] = "Nåle på verdenskortet",
	["World map tooltip"] = "Tooltip på verdenskortet",
	["World map tooltip with a zone's level and gathering ranges, dungeons and territory, and an optional toast when you enter a zone."] = "Tooltip på verdenskortet med en zones level- og indsamlingsintervaller, dungeons og territorium, og en valgfri pop op-besked når du kommer ind i en zone.",
	["World map, quest log, flight map, battlefield map and UI widgets: skin, position, scale, coordinates and fading."] = "Verdenskort, questlog, flyvekort, slagmarkskort og UI-widgets: skin, placering, skala, koordinater og toning.",
	["World marker"] = "Verdensmarkør",
	["World marker %d"] = "Verdensmarkør %d",
	["World markers"] = "Verdensmarkører",
	["Worn"] = "Båret",
	["Worn gear shows orange and counts in the summary, low gear shows red. Both thresholds are set once for every module, on the General page (Clock and durability)."] = "Slidt udstyr vises i orange og tæller med i resuméet, udstyr med lav holdbarhed vises i rødt. Begge grænser sættes én gang for alle moduler på siden Generelt (Ur og holdbarhed).",
	["Worn · BiS"] = "Båret · BiS",
	["WoW: Forever already shows quest levels in the quest log and quest tracker."] = "WoW: Forever viser allerede questlevels i questloggen og questtrackeren.",
	["WoW: Forever position, checked in game."] = "WoW: Forever-placering, tjekket i spillet.",
	["Wowhead"] = "Wowhead",
	["Wowhead address for what the tooltip shows (or your target)"] = "Wowhead-adresse til det tooltippen viser (eller dit mål)",
	["Wowhead link"] = "Wowhead-link",
	["Wowhead site"] = "Wowhead-udgave",
	["Write the game's combat log in the chosen instances. Logging started here stops 30 seconds after you leave."] = "Gem spillets kamplog i de valgte instanser. Automatisk logning stopper 30 sekunder efter du forlader instansen.",
	["Write the level time in your accent color."] = "Skriv leveltiden i din accentfarve.",
	["Write the macro with a live check and the condition builder."] = "Skriv makroen med løbende tjek og betingelsesbyggeren.",
	["Write the name of the cut, then its gold."] = "Skriv navnet på andelen og derefter dens guld.",
	["Write the numbers in your accent color."] = "Skriv tallene i din accentfarve.",
	["Write the row labels in your accent color instead of gray."] = "Skriv rækkens etiketter i din accentfarve i stedet for gråt.",
	["Write the spell names in the row; off with icons on shows icons only."] = "Skriv evnenavnene i rækken. Er det slået fra og ikoner slået til, vises kun ikoner.",
	["write your Player Notes note on this player"] = "skriv din note fra Spillernoter om denne spiller",
	["Writes the name, icon and text to the game's macro (out of combat)."] = "Skriver navn, ikon og tekst til spillets makro (uden for kamp).",
	["Writes the value. EldoUI remembers your own value the first time, so Restore can put it back."] = "Skriver værdien. EldoUI husker din egen værdi første gang, så Gendan kan sætte den tilbage.",
	["Wrong facing"] = "Forkert retning",
	["X offset"] = "X-forskydning",
	["x y [title], or zone x y [title]. Enter adds, Esc closes."] = "x y [titel] eller zone x y [titel]. Enter tilføjer, Esc lukker.",
	["XP and reputation"] = "XP og omdømme",
	["XP and Reputation Bars"] = "XP- og omdømmebjælker",
	["XP bar text always visible"] = "XP-bjælkens tekst altid synlig",
	["XP bonus"] = "XP-bonus",
	["XP bonus line"] = "Linje for XP-bonus",
	["XP color"] = "XP-farve",
	["XP food"] = "XP-mad",
	["XP numbers always shown, reward values, tracker button, zone tracking and flight timer. Quests stay yours to accept."] = "XP-tal altid vist, belønningsværdier, trackerknap, zonesporing og flyvenedtælling. Du accepterer stadig selv dine quests.",
	["XP per hour"] = "XP pr. time",
	["XP to the level cap"] = "XP til levelgrænsen",
	["Yards"] = "Yards",
	["Yards for the command below. The game keeps the value within its own limit and remembers it for this character."] = "Yards til kommandoen nedenfor. Spillet holder værdien inden for sin egen grænse og husker den for denne karakter.",
	["Yards to the waypoint, in a straight line."] = "Yards til waypointet i lige linje.",
	["Yellow, orange and red from the game's threat status."] = "Gul, orange og rød efter spillets aggrostatus.",
	["You are in combat"] = "Du er i kamp",
	["You are on"] = "Du er på",
	["You are on a new layer."] = "Du er på et nyt layer.",
	["You are on a new layer. Leave the group to stay here."] = "Du er på et nyt layer. Forlad gruppen for at blive her.",
	["You are on this quest"] = "Du har denne quest",
	["You can only start from the talents of the class you play."] = "Du kan kun starte ud fra talenterne i den klasse du spiller.",
